// Lektionen 55–66 (Offenbarungsreihenfolge, Kairoer Chronologie) – späte mekkanische Suren
window.LEKTIONEN9 = [
// ───────────────────────── Lektion 55: Al-Anʿām ─────────────────────────
{
sure: 6, offb: 55, name: "Al-Anʿām", arab: "سُورَةُ الْأَنْعَامِ", de: "Das Vieh", verse: 165, ort: "Mekka",
zeit: "Spätmekkanisch – die große Tauhīd-Sure, offenbart in der Phase härtester Ablehnung vor der Hidschra",
kurz: "Al-Anʿām ist die umfassendste Tauhīd-Sure Mekkas: Sie führt alle Argumente gegen den Götzendienst zusammen – aus der Schöpfung, aus der Vernunft, aus der Geschichte. Ihr Herzstück ist Ibrāhīms Suche nach Gott: Er schaut auf Stern, Mond und Sonne und sagt bei jedem, als er untergeht: „Ich liebe nicht die Untergehenden.“ Dann kommt sein Bekenntnis: „Ich wende mein Gesicht Dem zu, Der die Himmel und die Erde erschaffen hat.“ Die Sure zerlegt auch die erfundenen Speise- und Opferregeln der Araber, die Allah ‚Anteile' am Vieh zuschrieben – daher ihr Name. Und sie gibt in 6:151–153 die „zehn Gebote“ des Islam. Am Ende steht das Bekenntnis, das jeder Muslim im Eröffnungsgebet spricht: „Mein Gebet, mein Opfer, mein Leben und mein Sterben gehören Allah, dem Herrn der Welten.“",
schluessel: {arab: "قُلْ إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ", ueb: "Sag: Mein Gebet und mein Opfer, mein Leben und mein Sterben gehören Allah, dem Herrn der Welten.", ref: "6:162"},
kontext: ["Al-Anʿām gehört zu den letzten großen Suren Mekkas. Die Fronten sind verhärtet: Die Quraisch verlangen ständig neue Wunder („Warum wird kein Engel auf ihn herabgesandt?“), die Muslime sind wenige und verfolgt. Die Sure antwortet nicht mit einem neuen Wunder, sondern mit einem Feuerwerk an Argumenten: Wer erschafft? Wer versorgt? Wer rettet aus der Finsternis von Land und Meer? Jede Antwort führt zu Allah allein.",
"Ein zweites Thema sind die selbst erfundenen Gesetze der Dschāhiliyya: Die Araber teilten Ernte und Vieh in einen ‚Anteil für Allah' und einen ‚Anteil für die Götzen' – und schoben im Zweifel Allahs Anteil den Götzen zu (6:136). Sie erklärten bestimmte Tiere für verboten, andere nur für Männer erlaubt, und töteten ihre Kinder aus Angst vor Armut. Ibn ʿAbbās sagte dazu: „Wenn es dich freut, die Unwissenheit der Araber kennenzulernen, dann lies, was nach Vers 130 in Sure al-Anʿām steht“ (Sahih al-Buchari, Nr. 3524).",
"Die Überlieferung, die Sure sei auf einmal mit 70.000 Engeln herabgekommen, ist in der Tafsir-Literatur bekannt, ihre Ketten sind aber nach den Hadith-Kritikern schwach. Sicher ist: Die Sure bildet inhaltlich einen geschlossenen Block, ein Grundlagenbuch des Tauhīd."],
asbab: ["Für die Sure als Ganze ist kein einzelner Anlass sahih überliefert. Zu 6:82 („Diejenigen, die glauben und ihren Glauben nicht mit Unrecht vermischen …“) ist die Reaktion der Gefährten gesichert: Sie erschraken – „Wer von uns tut sich nicht selbst Unrecht?“ – und der Prophet ﷺ erklärte, gemeint sei Schirk, wie Luqmān sagt: „Schirk ist ein gewaltiges Unrecht“ (31:13) (Sahih al-Buchari, Nr. 32; Sahih Muslim, Nr. 124)."],
begriffe: [
 {arab: "الْأَنْعَام", tr: "al-anʿām", wurzel: "n-ʿ-m", erkl: "Das Vieh (Kamele, Rinder, Schafe, Ziegen) – verwandt mit niʿma (Gabe): Das Vieh war die große Gabe Allahs an die Araber. Die Sure zeigt, wie man aus einer Gabe ein Götzenritual machen kann."},
 {arab: "حَنِيف", tr: "ḥanīf", wurzel: "ḥ-n-f", erkl: "Der Aufrichtige, der sich vom Götzendienst ab- und dem Einen zuwendet. Ibrāhīms Titel (6:79): „Ich wende mein Gesicht ḥanīfan Dem zu, Der die Himmel und die Erde erschaffen hat.“"},
 {arab: "الْآفِلِين", tr: "al-āfilīn", wurzel: "ʾ-f-l", erkl: "„Die Untergehenden“ (6:76) – Ibrāhīms Kriterium: Was untergeht, verschwindet, sich verändert, kann nicht Gott sein. Ein Argument, das gegen jeden vergänglichen ‚Gott' greift – Sterne, Menschen, Geld, Ideologien."},
 {arab: "مَفَاتِح الْغَيْب", tr: "mafātiḥ al-ġaib", wurzel: "f-t-ḥ / ġ-y-b", erkl: "„Die Schlüssel des Verborgenen“ (6:59) – nur Allah hat sie. Der Prophet ﷺ nannte fünf, die in 31:34 stehen (siehe Lektion 57). „Kein Blatt fällt herab, ohne dass Er es weiß.“"},
 {arab: "صِرَاطِي مُسْتَقِيمًا", tr: "ṣirāṭī mustaqīman", wurzel: "ṣ-r-ṭ / q-w-m", erkl: "„Dies ist Mein Weg, gerade – so folgt ihm und folgt nicht den (anderen) Wegen“ (6:153) – der Abschluss der zehn Gebote. Ein Weg, viele Abzweigungen."},
 {arab: "نُسُك", tr: "nusuk", wurzel: "n-s-k", erkl: "Opfer/Kultakt (6:162) – im engeren Sinn das Schlachtopfer, im weiteren jeder Gottesdienst. Gegen die Götzenopfer der Araber: Auch das Schlachten gehört Allah allein."}
],
tafsir: [
 {vers: "Verse 1–73: Argumente und Einwände", text: "Die Sure beginnt mit Lob für den Schöpfer von Licht und Finsternis – „und doch stellen die Ungläubigen ihrem Herrn andere gleich“. Dann Antworten auf die Wunderforderungen: Selbst wenn Allah ihnen eine Schrift auf Papier herabsendete, die sie anfassen könnten, würden sie sagen: „Das ist nur Zauberei“ (6:7). Ibn Kathīr: Der Unglaube ist eine Entscheidung des Herzens, keine Frage fehlender Beweise (vgl. Lektion 37, Mondspaltung). Zentral 6:59: „Bei Ihm sind die Schlüssel des Verborgenen … kein Blatt fällt herab, ohne dass Er es weiß“ – und 6:65 die Warnung vor Strafe von oben, von unten und durch Spaltung untereinander. Dschābir berichtet, dass der Prophet ﷺ bei den ersten beiden sagte: „Ich suche Zuflucht bei Deinem Angesicht“, bei der dritten (Spaltung, gegenseitige Gewalt): „Das ist leichter“ (Sahih al-Buchari, Nr. 4628) – Spaltung ist die Strafe, die eine Umma sich selbst zufügt."},
 {vers: "Verse 74–94: Ibrāhīms Suche", text: "Ibrāhīm kritisiert seinen Vater Āzar: „Nimmst du Götzenbilder zu Göttern?“ Dann die berühmte Szene: Er sieht einen Stern – „Das ist mein Herr“ –, doch er geht unter; dann den Mond, dann die Sonne, „das ist größer“ – und alle gehen unter. Die Mufassirūn (u. a. Ibn Kathīr) betonen: Ibrāhīm zweifelte nicht selbst, sondern führte seinem Volk eine Debatte vor, um ihre Sternverehrung von innen her zu widerlegen. Sein Ergebnis: „Ich wende mein Gesicht Dem zu, Der Himmel und Erde erschaffen hat.“ Als sie ihm drohen, fragt er: „Welche der beiden Parteien hat mehr Anrecht auf Sicherheit?“ – und Allah antwortet in 6:82: die, die glauben und ihren Glauben nicht mit Schirk vermischen. Dann eine Liste von 18 Propheten (6:83–86) und der Satz an Muhammad ﷺ: „Das sind die, die Allah rechtgeleitet hat, so folge ihrer Rechtleitung“ (6:90)."},
 {vers: "Verse 95–135: Schöpfung, Einflüsterer, Verantwortung", text: "„Allah spaltet das Korn und den Kern“ (6:95, vgl. al-Falaq in Lektion 20), Er spaltet den Morgen, macht die Nacht zur Ruhe – der Kosmos als lesbares Buch. 6:103: „Die Blicke erfassen Ihn nicht, Er aber erfasst die Blicke“ – in dieser Welt sieht Ihn niemand; das Schauen im Paradies (Lektion 31) widerspricht dem nicht, denn ‚erfassen' (idrāk) heißt umfassen. 6:108 setzt eine wichtige Regel für Gespräche mit Andersgläubigen: „Beschimpft nicht die, die sie neben Allah anrufen, sonst beschimpfen sie Allah in feindseliger Weise ohne Wissen.“ Al-Qurṭubī leitet daraus ab: Eine erlaubte Handlung wird verboten, wenn sie zu etwas Schlimmerem führt (sadd adh-dharāʾiʿ). Dann 6:112: Jeder Prophet hatte Feinde, „Satane unter den Menschen und Dschinn“ – vgl. Lektion 21."},
 {vers: "Verse 136–150: die erfundenen Gesetze", text: "Die Sure seziert die Dschāhiliyya-Religion: der ‚Anteil Allahs', die verbotenen Tiere, die Kindstötung „aus Armut“ (6:137, 140). 6:140: „Verloren haben diejenigen, die ihre Kinder in Torheit ohne Wissen töten und verbieten, womit Allah sie versorgt hat.“ Dann die Rechtsfrage: Wer darf verbieten? Nur Allah – „Sag: Bringt eure Zeugen“ (6:150). 6:145 nennt die Grundliste des Verbotenen bei Speisen: Verendetes, ausgeflossenes Blut, Schweinefleisch, und was für einen anderen als Allah geschlachtet wurde. As-Saʿdī: Die größte Sünde nach dem Schirk ist, im Namen Gottes zu verbieten, was Er erlaubt hat – oder umgekehrt."},
 {vers: "Verse 151–165: die zehn Gebote und das Schlussbekenntnis", text: "„Sag: Kommt, ich trage vor, was euer Herr euch verboten hat“: (1) Ihm nichts beigesellen, (2) zu den Eltern gut sein, (3) Kinder nicht aus Armut töten – „Wir versorgen euch und sie“, (4) sich den Schändlichkeiten nicht nähern, offen oder verborgen, (5) niemanden zu Unrecht töten, (6) dem Vermögen der Waise nicht nahe kommen, außer auf beste Weise, (7) volles Maß und Gewicht geben, (8) gerecht sprechen, „auch wenn es um einen Verwandten geht“, (9) Allahs Bund erfüllen, (10) dem geraden Weg folgen und nicht den Abzweigungen (6:151–153). Ibn Masʿūd berichtet, wie der Prophet ﷺ dazu eine gerade Linie in den Sand zog und daneben viele Seitenlinien: „Das ist der Weg Allahs – und das sind Wege, auf jedem sitzt ein Satan, der dazu ruft“ (Musnad Aḥmad, Nr. 4142; hasan). Das Ende ist Bekenntnis: „Mein Gebet, mein Opfer, mein Leben, mein Sterben gehören Allah“ (6:162) und die Erinnerung an die Verantwortung: „Keine lasttragende (Seele) trägt die Last einer anderen“ (6:164, vgl. 53:38 in Lektion 23)."}
],
ahadith: [
 {text: "Ibn Masʿūd: Die Gefährten fragten nach 6:82: „Wer von uns tut sich nicht selbst Unrecht?“ – Der Prophet ﷺ: „Es ist nicht so, wie ihr denkt; es ist so, wie Luqmān zu seinem Sohn sagte: Schirk ist ein gewaltiges Unrecht.“", quelle: "Sahih al-Buchari, Nr. 32; Sahih Muslim, Nr. 124"},
 {text: "Ibn ʿAbbās: „Wenn es dich freut, die Unwissenheit der Araber kennenzulernen, dann lies, was über Vers 130 in Sure al-Anʿām steht: ‚Verloren haben diejenigen, die ihre Kinder in Torheit töten …‘“", quelle: "Sahih al-Buchari, Nr. 3524"},
 {text: "Die Schlüssel des Verborgenen sind fünf, die nur Allah kennt – dann rezitierte er 31:34.", quelle: "Sahih al-Buchari, Nr. 4627"},
 {text: "Ibn Masʿūd: Der Prophet ﷺ zog eine gerade Linie und daneben Seitenlinien und rezitierte 6:153.", quelle: "Musnad Aḥmad, Nr. 4142; hasan"}
],
hanafi: "Zwei hanafitische Anwendungen aus dieser Sure: (1) 6:121 („Esst nicht von dem, worüber der Name Allahs nicht ausgesprochen wurde“): Hanafitisch ist die Basmala beim Schlachten Bedingung – wird sie absichtlich weggelassen, ist das Fleisch nicht erlaubt; wird sie vergessen, ist es erlaubt. (2) 6:141 („Gebt am Tag der Ernte ihr Recht“): Abū Ḥanīfa leitete daraus die ʿUschr-Abgabe auf Ernteerträge ab – nach seiner Meinung auf jeden Ertrag, ohne Mindestmenge (niṣāb); seine Schüler Abū Yūsuf und Muḥammad setzten eine Mindestmenge von fünf Wasq an.",
umsetzung: [
 "Sprich das Eröffnungsgebet bewusst: In der hanafitischen Praxis beginnt das Gebet mit dem Thanāʾ, viele kennen aber auch 6:162 aus dem Tawadschdschuh – lerne 6:162 und mach ihn zu deinem Lebensmotto: Alles, auch Leben und Tod, gehört Allah.",
 "Mach den Ibrāhīm-Test (6:76): Was in meinem Leben ist ein ‚untergehender Stern', an den ich mein Herz hänge? Was vergeht, kann mich nicht tragen.",
 "Lerne die zehn Gebote aus 6:151–153 auswendig (auf Deutsch reicht für den Anfang) und lehre sie deinen Kindern oder Schülern – sie sind die kürzeste Ethik des Korans.",
 "Halte 6:108 im Gespräch: Nie über das spotten, was anderen heilig ist – Argumente ja, Beleidigung nein."
]
},

// ───────────────────────── Lektion 56: Aṣ-Ṣāffāt ─────────────────────────
{
sure: 37, offb: 56, name: "Aṣ-Ṣāffāt", arab: "سُورَةُ الصَّافَّاتِ", de: "Die sich Reihenden", verse: 182, ort: "Mekka",
zeit: "Mittelmekkanisch – Antwort auf die Behauptung der Quraisch, die Engel seien ‚Töchter Allahs‘",
kurz: "Die Sure beginnt mit den Engeln, die in Reihen stehen – und widerlegt damit den Glauben der Mekkaner, Engel seien ‚Töchter Allahs'. Dann die Höllenszene mit dem Zaqqūm-Baum, dann eine Reihe von Prophetengeschichten, alle mit demselben Schluss: „Friede sei auf …“ Ihr Mittelpunkt ist eine der bewegendsten Szenen des Korans: Ibrāhīm träumt, dass er seinen Sohn opfert, und fragt ihn: „Was meinst du?“ – Der Sohn antwortet: „Mein Vater, tu, was dir befohlen wird; du wirst mich, so Allah will, unter den Geduldigen finden.“ Als beide sich ergeben, ruft Allah: „O Ibrāhīm, du hast das Traumgesicht erfüllt“ – und löst den Sohn mit einem gewaltigen Opfertier aus. Daher kommt das Opferfest. Danach Yūnus im Bauch des Fisches. Die Sure endet mit den drei Versen, mit denen viele Muslime jede Versammlung schließen: „Gepriesen sei dein Herr …, Friede auf den Gesandten, und Lob sei Allah, dem Herrn der Welten.“",
schluessel: {arab: "قَالَ يَا أَبَتِ افْعَلْ مَا تُؤْمَرُ ۖ سَتَجِدُنِي إِن شَاءَ اللَّهُ مِنَ الصَّابِرِينَ", ueb: "Er sagte: Mein Vater, tu, was dir befohlen wird. Du wirst mich, so Allah will, unter den Geduldigen finden.", ref: "37:102"},
kontext: ["Die Quraisch hatten eine eigene Engel-Theologie: Allah habe die Engel als Töchter (mit Dschinn-Frauen) gezeugt – während sie selbst Töchter verachteten (vgl. Lektion 23, 53:21). Die Sure antwortet mit einem Bild: Die Engel stehen in geordneten Reihen, sie preisen und gehorchen – Diener, keine Familie. Am Ende sprechen die Engel selbst: „Keiner von uns, der nicht seinen bekannten Platz hätte; wir sind es, die in Reihen stehen, und wir sind es, die (Allah) preisen“ (37:164–166).",
"Die Prophetenreihe (Nūḥ, Ibrāhīm, Mūsā und Hārūn, Ilyās, Lūṭ, Yūnus) ist eine Ermutigung für die bedrängte Gemeinde: Jede Geschichte endet mit Rettung und mit dem Ehrentitel „Friede sei auf …“ – und dem Satz: „So vergelten Wir den Gutes-Tuenden; er gehört zu Unseren gläubigen Dienern.“",
"Wer war der Sohn, der geopfert werden sollte? Die Mehrheit der Gelehrten und der starke Wortlaut sagen: Ismāʿīl – denn erst nach der Opferszene wird die Geburt Isḥāqs als neue frohe Botschaft verkündet (37:112). Das Opfern bei Minā, das Steinewerfen und das Opferfest erinnern alle an diese Szene."],
asbab: [
 {text: "Zu 37:62–65 (Zaqqūm-Baum): Als die Quraisch vom Zaqqūm-Baum in der Hölle hörten, spottete Abū Dschahl: „Zaqqūm sind doch Datteln mit Butter!“ und bewirtete seine Leute damit. Der Koran nennt den Baum „eine Prüfung für die Ungerechten“.", quelle: "Tafsir-Bericht (aṭ-Ṭabarī, Ibn Kathīr zu 37:62 und 17:60); keine Sahih-Kette"}
],
begriffe: [
 {arab: "الصَّافَّات", tr: "aṣ-ṣāffāt", wurzel: "ṣ-f-f", erkl: "„Die sich in Reihen Stellenden“ – die Engel in ihren Reihen der Anbetung. Der Prophet ﷺ fragte: „Wollt ihr euch nicht in Reihen stellen, wie die Engel bei ihrem Herrn?“ – dann erklärte er: Sie vervollständigen die vorderen Reihen und schließen die Lücken (Sahih Muslim, Nr. 430). Die Reihe im Gebet ist Engel-Ordnung."},
 {arab: "الزَّقُّوم", tr: "az-zaqqūm", wurzel: "z-q-m", erkl: "Der Baum, der am Grund der Hölle wächst, „seine Fruchtschäfte wie Köpfe von Satanen“ (37:65). Bild für die bittere Speise der Bewohner des Feuers – Gegenbild zu den Früchten des Paradieses."},
 {arab: "قَلْب سَلِيم", tr: "qalb salīm", wurzel: "s-l-m", erkl: "„Ein heiles Herz“ (37:84): „Als er (Ibrāhīm) mit einem heilen Herzen zu seinem Herrn kam“ – frei von Schirk, Groll und Hochmut. Der Titel des ganzen Tazkiya-Weges; vgl. 26:89."},
 {arab: "أَسْلَمَا", tr: "aslamā", wurzel: "s-l-m", erkl: "„Als beide sich ergeben hatten“ (37:103) – Vater und Sohn ergaben sich gemeinsam in Allahs Befehl. Islam in seiner reinsten Form: Hingabe ohne Bedingung."},
 {arab: "ذِبْح عَظِيم", tr: "dhibḥ ʿaẓīm", wurzel: "dh-b-ḥ", erkl: "„Ein gewaltiges Schlachtopfer“ (37:107), mit dem Allah den Sohn auslöste. Ursprung des Opferfestes (ʿĪd al-Aḍḥā) – vgl. Lektion 15 zum Kurban."},
 {arab: "الْمُسَبِّحِين", tr: "al-musabbiḥīn", wurzel: "s-b-ḥ", erkl: "„Die Preisenden“ (37:143): „Wäre er (Yūnus) nicht einer der Preisenden gewesen, wäre er in seinem Bauch geblieben bis zum Tag der Auferweckung.“ Der Dhikr in guten Zeiten rettet in schlechten."}
],
tafsir: [
 {vers: "Verse 1–74: Engel, Spötter und das Paradies", text: "Drei Schwüre bei den Engeln, dann: „Euer Gott ist wahrlich Einer.“ Die Satane, die am Himmel lauschen wollen, werden von Feuerpfeilen verjagt (vgl. Lektion 40). Dann die Spötter: „Wenn wir gestorben sind … sollen wir wirklich auferweckt werden?“ Antwort: „Ja – und ihr werdet gedemütigt sein.“ Es folgt ein Gespräch im Paradies: Ein Paradiesbewohner erinnert sich an einen Freund, der ihn im Diesseits vom Glauben abbringen wollte; er schaut hinab und sieht ihn mitten im Feuer: „Bei Allah, beinahe hättest du mich ins Verderben gestürzt!“ (37:56). Ibn Kathīr: Eine Warnung vor falschen Freunden (vgl. 25:28 in Lektion 42)."},
 {vers: "Verse 75–113: Nūḥ und Ibrāhīm", text: "Nūḥ rief, „und welch trefflicher Erhörer sind Wir!“ Dann Ibrāhīm: Er zerschlägt die Götzen seines Volkes, sie wollen ihn verbrennen, Allah rettet ihn. Er sagt: „Ich gehe zu meinem Herrn, Er wird mich rechtleiten“ – und bittet um einen rechtschaffenen Sohn. Dann die Opferszene (37:102–107): Ibrāhīm teilt dem Sohn den Traum mit – er zwingt ihn nicht, er fragt ihn: „Schau, was meinst du?“ As-Saʿdī: Das ist Erziehung mit Würde – der Sohn soll den Gehorsam als eigene Entscheidung annehmen. Der Sohn antwortet mit Gehorsam und mit inschāʾAllāh – er verlässt sich nicht auf seine eigene Stärke. Als beide sich ergeben hatten und Ibrāhīm ihn auf die Stirn legte, rief Allah: „Du hast das Traumgesicht erfüllt – so vergelten Wir den Gutes-Tuenden. Das war die offenkundige Prüfung.“ Die Prüfung war nicht das Schlachten, sondern die Bereitschaft: Allah wollte das Herz, nicht das Blut (vgl. 22:37)."},
 {vers: "Verse 114–148: Mūsā, Ilyās, Lūṭ, Yūnus", text: "Mūsā und Hārūn werden gerettet, Ilyās ruft gegen den Götzen Baʿl: „Ruft ihr Baʿl an und verlasst den besten Schöpfer?“ Lūṭ wird gerettet. Dann Yūnus: Er lief ohne Erlaubnis von seinem Volk weg, „zum vollbeladenen Schiff“, verlor beim Los, wurde ins Meer geworfen und vom Fisch verschluckt, „während er sich Tadel zuzog“. Sein Dhikr rettete ihn – nach 21:87 betete er im Bauch des Fisches: „Es gibt keinen Gott außer Dir, gepriesen seist Du, ich gehörte zu den Ungerechten.“ Der Prophet ﷺ sagte, kein Muslim betet mit diesem Gebet um etwas, ohne dass Allah ihn erhört (at-Tirmidhī, Nr. 3505; sahih). Dann wird er geschwächt an den Strand geworfen, ein Kürbisstrauch spendet ihm Schatten – und sein Volk von über hunderttausend glaubt (37:147–148, vgl. Sure Yūnus)."},
 {vers: "Verse 149–182: Abrechnung mit der Engel-Theologie", text: "„Hat dein Herr Töchter und sie Söhne? Oder haben Wir die Engel weiblich erschaffen, während sie Zeugen waren?“ – die Sure fragt nach Beweisen und findet keine. Auch die Behauptung einer Verwandtschaft zwischen Allah und den Dschinn wird zurückgewiesen. Die Engel selbst bezeugen ihre Dienerschaft (37:164–166). Dann die Zusage an die Gesandten: „Unser Wort ist an Unsere Diener ergangen: Sie werden gewiss unterstützt werden, und Unser Heer wird siegen“ (37:171–173). Der Schluss ist ein dreifaches Lob: „Gepriesen sei dein Herr, der Herr der Macht, über das, was sie beschreiben; und Friede sei auf den Gesandten; und Lob sei Allah, dem Herrn der Welten.“"}
],
ahadith: [
 {text: "„Wollt ihr euch nicht in Reihen stellen, wie die Engel bei ihrem Herrn?“ – Sie vervollständigen die vorderen Reihen und stehen dicht in der Reihe.", quelle: "Sahih Muslim, Nr. 430"},
 {text: "Ibn ʿUmar: Der Prophet ﷺ befahl uns, (das Gebet) leicht zu halten – und leitete uns im Gebet mit (Sure) aṣ-Ṣāffāt.", quelle: "Sunan an-Nasāʾī, Nr. 826; hasan"},
 {text: "„Das Gebet des Dhū n-Nūn (Yūnus) im Bauch des Fisches: Lā ilāha illā anta, subḥānaka, innī kuntu mina ẓ-ẓālimīn – kein Muslim betet damit um etwas, ohne dass Allah ihn erhört.“", quelle: "Sunan at-Tirmidhī, Nr. 3505; sahih"},
 {text: "„Sagt nicht, ich sei besser als Yūnus ibn Mattā.“", quelle: "Sahih al-Buchari, Nr. 3395; Sahih Muslim, Nr. 2377"}
],
hanafi: "Die Opferszene ist die Grundlage der udḥiya (Kurban). Wie in Lektion 15 erklärt, ist das Opfern am Opferfest in der hanafitischen Schule für jeden sesshaften, volljährigen Muslim mit Nisāb-Vermögen wādschib. Hanafitisch gilt außerdem: Ein Schaf oder eine Ziege reicht für eine Person; an einem Rind oder Kamel können sich bis zu sieben Personen beteiligen – die Opferzeit sind die drei Festtage (10.–12. Dhū l-Ḥidschdscha) nach dem Festgebet.",
umsetzung: [
 "Erziehe wie Ibrāhīm (37:102): Frag deine Kinder oder Schüler nach ihrer Meinung, statt nur zu befehlen – Gehorsam aus Einsicht hält länger.",
 "Lerne das Gebet des Yūnus (Lā ilāha illā anta, subḥānaka, innī kuntu mina ẓ-ẓālimīn) und sprich es in jeder Not – mit Tirmidhī-Beleg.",
 "Stell dich im Gebet in die Reihe wie die Engel: gerade, dicht, ohne Lücken – das ist die Sunna dieser Sure.",
 "Schließe Versammlungen und Lernkreise mit 37:180–182 (subḥāna rabbika rabbi l-ʿizzati ʿammā yaṣifūn …) – viele Gelehrte empfehlen das als guten Abschluss."
]
},

// ───────────────────────── Lektion 57: Luqmān ─────────────────────────
{
sure: 31, offb: 57, name: "Luqmān", arab: "سُورَةُ لُقْمَانَ", de: "Luqmān", verse: 34, ort: "Mekka",
zeit: "Mittel- bis spätmekkanisch – als die Quraisch versuchten, die Menschen mit Unterhaltung vom Koran abzulenken",
kurz: "Die Erziehungs-Sure des Korans. Im Mittelpunkt steht Luqmān, ein weiser Mann (kein Prophet nach Meinung der Mehrheit), dem Allah Weisheit gab. Er gibt seinem Sohn zehn Lebenslektionen: Gesell Allah nichts bei – denn Schirk ist ein gewaltiges Unrecht. Allah sieht auch das Senfkorn im Felsen. Verrichte das Gebet, gebiete das Gute, verbiete das Schlechte, sei geduldig. Dreh den Menschen nicht hochmütig die Wange zu, geh nicht übermütig auf der Erde, halte Maß im Gang und senke deine Stimme. Mitten in diese Vater-Sohn-Lektion fügt Allah selbst die Pflicht gegenüber den Eltern ein – besonders der Mutter, die „Schwäche über Schwäche“ trug. Die Sure beginnt mit der Warnung vor „Zerstreuungsgerede“, das vom Weg Allahs abhält, und endet mit den fünf Dingen, die nur Allah weiß.",
schluessel: {arab: "يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ ۖ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ", ueb: "Mein lieber Sohn, geselle Allah nichts bei, denn Schirk ist wahrlich ein gewaltiges Unrecht.", ref: "31:13"},
kontext: ["Die Quraisch merkten, dass der Koran die Herzen erreichte. Eine ihrer Gegenstrategien: Unterhaltung. Die Tafsir-Werke berichten von an-Naḍr ibn al-Ḥārith, der persische Heldengeschichten (Rustam und Isfandiyār) und Sängerinnen kaufte, um die Leute vom Koran abzulenken. Dazu passt 31:6: „Unter den Menschen gibt es manchen, der Zerstreuungsgerede (lahw al-ḥadīth) kauft, um ohne Wissen vom Weg Allahs abirren zu lassen.“ Ibn Masʿūd schwor dreimal, damit sei der Gesang gemeint (Tafsir-Bericht bei aṭ-Ṭabarī; al-Ḥākim stuft die Kette als sahih ein).",
"Die Antwort des Korans auf billige Unterhaltung ist echte Weisheit: Luqmāns Rat an seinen Sohn. Luqmān war nach den Überlieferungen ein weiser Mann aus Afrika (Nubien/Äthiopien wird genannt), bekannt bei den Arabern. Der Koran nimmt ein Vorbild, das die Araber schon kannten und schätzten – und füllt es mit Tauhīd.",
"Die Sure ist ein Lehrbuch für Eltern und Lehrer: Luqmān spricht seinen Sohn mit yā bunayya an – „mein lieber kleiner Sohn“, eine zärtliche Verkleinerungsform. Ernste Inhalte in liebevoller Sprache: Das ist die Methode."],
asbab: [
 {text: "Zu 31:6 (lahw al-ḥadīth): Nach den Tafsir-Berichten bezogen auf an-Naḍr ibn al-Ḥārith, der Geschichten und Sängerinnen einsetzte, um die Menschen vom Koran abzulenken; Ibn Masʿūd deutete den Ausdruck als Gesang.", quelle: "Tafsir aṭ-Ṭabarī und Ibn Kathīr zu 31:6; al-Ḥākim (Ibn Masʿūd), sahih nach seiner Einstufung"},
 {text: "Zu 31:15 („Wenn sie dich drängen, Mir etwas beizugesellen … dann gehorche ihnen nicht, doch geh mit ihnen im Diesseits in rechtlicher Weise um“): Nach Muslim, Nr. 1748 bezogen auf Saʿd ibn Abī Waqqāṣ, dessen Mutter in den Hungerstreik trat, damit er den Islam aufgebe.", quelle: "Sahih Muslim, Nr. 1748"}
],
begriffe: [
 {arab: "الْحِكْمَة", tr: "al-ḥikma", wurzel: "ḥ-k-m", erkl: "Weisheit – das richtige Wissen am richtigen Ort zur richtigen Zeit. Luqmān bekam die Ḥikma (31:12), und ihr erstes Zeichen ist: „Sei Allah dankbar.“ Wahre Weisheit beginnt mit Dankbarkeit."},
 {arab: "لَهْو الْحَدِيث", tr: "lahw al-ḥadīth", wurzel: "l-h-w", erkl: "„Zerstreuungsgerede“ (31:6) – alles, was ablenkt und vom Weg Allahs abhält: nach Ibn Masʿūd Gesang, nach anderen leere Geschichten und Gerede. Dieselbe Wurzel wie alhākum (Lektion 16)."},
 {arab: "وَهْنًا عَلَىٰ وَهْنٍ", tr: "wahnan ʿalā wahn", wurzel: "w-h-n", erkl: "„Schwäche über Schwäche“ (31:14) – die Mutter trug das Kind unter wachsender Schwäche, dann zwei Jahre Stillzeit. Darum: „Sei Mir und deinen Eltern dankbar.“"},
 {arab: "مِثْقَال حَبَّة مِّنْ خَرْدَل", tr: "mithqāl ḥabba min chardal", wurzel: "th-q-l", erkl: "„Das Gewicht eines Senfkorns“ (31:16): Selbst wenn es in einem Felsen, im Himmel oder in der Erde wäre – Allah bringt es hervor. Das Bewusstsein, dass nichts verloren geht, ist die Grundlage der Selbsterziehung."},
 {arab: "لَا تُصَعِّرْ خَدَّكَ", tr: "lā tuṣaʿʿir chaddak", wurzel: "ṣ-ʿ-r", erkl: "„Wende deine Wange nicht (hochmütig) von den Menschen ab“ (31:18) – ṣaʿar ist eine Krankheit bei Kamelen, die den Hals schief macht. Hochmut als Haltungsschaden."},
 {arab: "وَاغْضُضْ مِن صَوْتِكَ", tr: "wa-ġḍuḍ min ṣautik", wurzel: "ġ-ḍ-ḍ", erkl: "„Und dämpfe deine Stimme“ (31:19) – „die widerwärtigste der Stimmen ist die Stimme der Esel“. Lautstärke ersetzt keine Argumente; leise Stimme ist ein Zeichen innerer Ruhe."}
],
tafsir: [
 {vers: "Verse 1–11: die Rechtschaffenen und die Ablenker", text: "Der Koran ist „Rechtleitung und Barmherzigkeit für die Gutes-Tuenden (muḥsinīn)“, die beten, Zakat geben und vom Jenseits überzeugt sind. Dann das Gegenbild: der, der lahw al-ḥadīth kauft und die Verse verspottet – „als hätte er Taubheit in den Ohren“. Ibn Kathīr: Die Sure stellt zwei Arten von ‚Hören' gegenüber: das Hören des Korans, das leitet, und das Hören der Ablenkung, das verstopft. Dann Schöpfungszeichen: Himmel ohne sichtbare Stützen, Berge, Regen – „Das ist Allahs Schöpfung; zeigt mir, was die erschaffen haben, die ihr neben Ihm anbetet!“"},
 {vers: "Verse 12–19: Luqmāns Lektionen", text: "Die Lektionen in Reihenfolge: (1) Kein Schirk – das größte Unrecht, weil es Allah Sein Recht nimmt (31:13). (2) Allahs Einschub über die Eltern (31:14–15): Dankbarkeit gegenüber Allah und den Eltern; aber: Wenn sie zum Schirk drängen, „gehorche ihnen nicht – doch begleite sie im Diesseits auf rechtliche Weise“. (3) Allahs Wissen bis zum Senfkorn (31:16). (4) Gebet, (5) das Gute gebieten, (6) das Schlechte verbieten, (7) Geduld bei dem, was dich trifft – „das gehört zur Entschlossenheit in den Angelegenheiten“ (31:17). (8) Keine hochmütige Abwendung von Menschen, (9) kein übermütiger Gang, (10) Maß im Gehen, gedämpfte Stimme (31:18–19). As-Saʿdī: Die Reihenfolge ist Pädagogik – erst Glaube, dann Gottesdienst, dann soziale Verantwortung, dann Charakter. Wer bei der Höflichkeit beginnt und den Tauhīd überspringt, baut ohne Fundament."},
 {vers: "Verse 20–30: Dankbarkeit und Hingabe", text: "„Habt ihr nicht gesehen, dass Allah euch dienstbar gemacht hat, was in den Himmeln und auf der Erde ist, und Seine Gaben über euch ausgebreitet hat, äußerlich und innerlich?“ (31:20). Die Gelehrten nennen als äußere Gaben Gesundheit, Versorgung, Schönheit; als innere den Glauben, den Verstand, die verdeckten Fehler. Dann der Vers von der festen Handhabe: „Wer sein Gesicht Allah hingibt und dabei Gutes tut, der hat die festeste Handhabe ergriffen“ (31:22). Und der Satz über Allahs Worte: Wären alle Bäume Schreibrohre und das Meer Tinte mit sieben weiteren Meeren – Allahs Worte würden nicht erschöpft (31:27)."},
 {vers: "Verse 31–34: Schiff, Tag und die fünf Schlüssel", text: "Das Schiff auf dem Meer: Wenn Wellen wie Schattendächer sie bedecken, rufen die Menschen Allah aufrichtig an – und vergessen Ihn an Land wieder (vgl. 17:67). Dann die Warnung: An jenem Tag kann kein Vater für seinen Sohn etwas leisten, und kein Sohn für seinen Vater. „Lasst euch nicht durch das diesseitige Leben täuschen, und lasst euch nicht durch den Täuscher (Satan) über Allah täuschen.“ Der letzte Vers nennt die fünf Schlüssel des Verborgenen: das Wissen um die Stunde, das Herabsenden des Regens, was im Mutterleib ist, was jemand morgen erwerben wird, in welchem Land er sterben wird (31:34). Der Prophet ﷺ zitierte diesen Vers im Hadith Dschibrīl (Sahih al-Buchari, Nr. 50; Sahih Muslim, Nr. 9). Zum Mutterleib erklären Gelehrte: Was das Wissen um ‚Junge oder Mädchen' per Ultraschall angeht, bleibt das umfassende Wissen um dieses Kind – sein Leben, seine Versorgung, sein Glück oder Unglück – allein bei Allah."}
],
ahadith: [
 {text: "Ein Mann fragte: „Wer hat das größte Anrecht auf meine gute Gesellschaft?“ – „Deine Mutter.“ – „Dann wer?“ – „Deine Mutter.“ – „Dann wer?“ – „Deine Mutter.“ – „Dann wer?“ – „Dein Vater.“", quelle: "Sahih al-Buchari, Nr. 5971; Sahih Muslim, Nr. 2548"},
 {text: "Asmāʾ fragte, ob sie ihre nichtmuslimische Mutter gut behandeln dürfe: „Ja, pflege die Verbindung zu deiner Mutter.“ – vgl. 31:15.", quelle: "Sahih al-Buchari, Nr. 2620; Sahih Muslim, Nr. 1003"},
 {text: "Im Hadith Dschibrīl über die Stunde: „… in fünf (Dingen), die niemand außer Allah kennt“ – dann rezitierte er 31:34.", quelle: "Sahih al-Buchari, Nr. 50; Sahih Muslim, Nr. 9"},
 {text: "„Niemand betritt das Paradies, in dessen Herzen ein Stäubchen Hochmut ist.“ – zu 31:18.", quelle: "Sahih Muslim, Nr. 91"}
],
hanafi: "Zu 31:6 (lahw al-ḥadīth) vertritt die klassische hanafitische Schule eine strenge Position: Musikinstrumente (maʿāzif) gelten als verboten; erlaubt bleiben nach den Fuqahāʾ etwa die Trommel (duff) bei Hochzeiten und Gesang ohne Instrumente mit erlaubtem Inhalt (vgl. Ibn ʿĀbidīn, Radd al-Muḥtār). Zu 31:14–15: Der Gehorsam gegenüber den Eltern ist in allem Erlaubten Pflicht; bei einem Befehl zur Sünde gilt der Grundsatz „Kein Gehorsam gegenüber einem Geschöpf im Ungehorsam gegen den Schöpfer“.",
umsetzung: [
 "Nimm Luqmāns zehn Lektionen als Elternprogramm oder Unterrichtsreihe: eine Lektion pro Woche, zehn Wochen – mit der Sprache yā bunayya: ernst im Inhalt, zärtlich im Ton.",
 "Prüfe dein lahw al-ḥadīth (31:6): Welcher Medienkonsum hält dich messbar vom Koran ab? Ersetze eine Stunde davon pro Woche durch Koran oder Wissen.",
 "Ehre deine Mutter nach dem Dreimal-Hadith: eine konkrete Geste diese Woche – Anruf, Besuch, Geschenk, Duʿā für sie.",
 "Übe 31:18–19 im Alltag: im Streit die Stimme senken, nicht von oben herab reden, ruhig gehen – Charakter zeigt sich zuerst im Körper."
]
},

// ───────────────────────── Lektion 58: Sabaʾ ─────────────────────────
{
sure: 34, offb: 58, name: "Sabaʾ", arab: "سُورَةُ سَبَإٍ", de: "Sabaʾ", verse: 54, ort: "Mekka",
zeit: "Spätmekkanisch – Lehrstück über Dankbarkeit und Undankbarkeit an zwei Beispielen: den Dāwūd-Leuten und dem Volk von Sabaʾ",
kurz: "Die Sure der zwei Familien: Auf der einen Seite die Familie Dāwūds, der Allah Macht, Werkstoffe und dienstbare Dschinn gab – mit dem Auftrag: „Arbeitet, ihr Leute Dāwūds, in Dankbarkeit! Doch wenige Meiner Diener sind dankbar.“ Auf der anderen Seite das Volk von Sabaʾ im Jemen: zwei Gärten rechts und links, ein großer Damm, ein „gutes Land und ein vergebender Herr“ – doch sie wandten sich ab, der Damm brach, und aus den Gärten wurde Gestrüpp. Dazwischen eine der feinsten Szenen des Korans: Sulaimān stirbt auf seinen Stab gestützt, und die Dschinn arbeiten weiter, weil sie es nicht merken – bis ein Holzwurm den Stab zerfrisst. So wurde klar: Die Dschinn kennen das Verborgene nicht. Die Sure endet mit dem Aufruf: „Ich ermahne euch nur zu einem: dass ihr für Allah aufsteht, zu zweit und einzeln, und dann nachdenkt.“",
schluessel: {arab: "اعْمَلُوا آلَ دَاوُودَ شُكْرًا ۚ وَقَلِيلٌ مِّنْ عِبَادِيَ الشَّكُورُ", ueb: "Arbeitet, ihr Leute Dāwūds, in Dankbarkeit! Doch wenige von Meinen Dienern sind dankbar.", ref: "34:13"},
kontext: ["Sabaʾ war ein reiches Königreich im Südwesten Arabiens (heutiger Jemen) mit der Hauptstadt Maʾrib. Sein berühmter Staudamm bewässerte große Gartenflächen; sein Bruch war den Arabern als historisches Ereignis bekannt und wurde sprichwörtlich. Die Sure erzählt diese bekannte Geschichte als Spiegel für Mekka: Auch ihr lebt von Gaben (vgl. Lektion 29, Quraisch) – und auch eure Gaben können verschwinden.",
"Farwa ibn Musaik al-Murādī fragte den Propheten ﷺ, ob Sabaʾ ein Land oder eine Frau sei. Er antwortete: Weder noch – Sabaʾ war ein Mann, der zehn Söhne hatte; sechs siedelten im Jemen, vier im Norden (at-Tirmidhī, Nr. 3222; hasan). Die Stämme Arabiens führten sich teils darauf zurück.",
"Die Sure antwortet zudem auf die Leugnung der Auferstehung und den Vorwurf, Muhammad ﷺ sei besessen. Ihre Methode ist ruhig: Sie lädt nicht zu Massendebatten ein, sondern zum stillen Nachdenken – zu zweit oder allein (34:46)."],
asbab: ["Für die Sure ist kein Einzelanlass sahih überliefert. Zu 34:46 („Ich bin für euch nur ein Warner vor einer strengen Strafe“): Ibn ʿAbbās verbindet die Formulierung mit der Ṣafā-Szene, als der Prophet ﷺ die Quraisch rief und sagte: „Ich bin für euch ein Warner vor einer strengen Strafe“ (Sahih al-Buchari, Nr. 4801; vgl. Lektion 6)."],
begriffe: [
 {arab: "شُكْرًا", tr: "schukran", wurzel: "sch-k-r", erkl: "„In Dankbarkeit (arbeitet)“ – Dankbarkeit nicht nur mit der Zunge, sondern als Arbeit: die Gabe so nutzen, wie der Geber es will. Ibn Kathīr: Dank ist mit Herz, Zunge und Tat."},
 {arab: "الشَّكُور", tr: "asch-schakūr", wurzel: "sch-k-r", erkl: "„Der sehr Dankbare“ – Intensivform. „Wenige Meiner Diener sind schakūr“ (34:13). Der Prophet ﷺ stand nachts, bis seine Füße anschwollen: „Soll ich nicht ein dankbarer Diener sein?“ (Sahih al-Buchari, Nr. 4837)."},
 {arab: "مِنسَأَة", tr: "minsaʾa", wurzel: "n-s-ʾ", erkl: "Der Stab Sulaimāns (34:14), auf den er sich stützte, als er starb. „Nur das Tier der Erde (der Holzwurm) zeigte ihnen seinen Tod an.“ Ein Stab, der zeigt: Selbst die Dschinn wissen nichts vom Verborgenen (vgl. Lektion 40)."},
 {arab: "سَيْل الْعَرِم", tr: "sail al-ʿarim", wurzel: "ʿ-r-m", erkl: "„Die Flut des Dammes“ (34:16) – der Bruch des Staudamms von Maʾrib. Aus zwei Gärten wurden „zwei Gärten mit bitterer Frucht, Tamarisken und wenigen Lotusbäumen“."},
 {arab: "أَحَادِيث", tr: "aḥādīth", wurzel: "ḥ-d-th", erkl: "„Wir machten sie zu Geschichten (aḥādīth)“ (34:19) – ein ganzes Volk wurde zum Gesprächsstoff. Die Araber sagten sprichwörtlich: ‚Sie zerstreuten sich wie die Leute von Sabaʾ‘."},
 {arab: "مَثْنَىٰ وَفُرَادَىٰ", tr: "mathnā wa-furādā", wurzel: "th-n-y / f-r-d", erkl: "„Zu zweit und einzeln“ (34:46): Steht für Allah auf und denkt nach – nicht in der aufgeheizten Menge, wo Gruppendruck herrscht, sondern im ruhigen Gespräch oder allein."}
],
tafsir: [
 {vers: "Verse 1–9: das Wissen Allahs und die Leugner", text: "Lob für Allah, Dem alles gehört. „Er weiß, was in die Erde eindringt und was aus ihr herauskommt, was vom Himmel herabkommt und was zu ihm aufsteigt“ (34:2). Die Leugner schwören, die Stunde komme nicht – Antwort: „Doch, bei meinem Herrn, sie wird gewiss zu euch kommen“ (34:3). Ihr zweiter Vorwurf: „Ein Mann, der euch erzählt, ihr würdet nach dem Zerfall neu erschaffen? Hat er eine Lüge erfunden oder ist er besessen?“ Ibn Kathīr: Der Koran antwortet mit einer Warnung – „Sehen sie denn nicht, was vor ihnen und hinter ihnen vom Himmel und der Erde ist?“ –, der Mensch ist ganz von Allahs Schöpfung umgeben."},
 {vers: "Verse 10–14: Dāwūd und Sulaimān", text: "Dāwūd: Die Berge und die Vögel preisen mit ihm, das Eisen wird weich in seiner Hand, und er fertigt Panzerhemden – mit dem Befehl: „Bemiss die Glieder richtig“ (34:11), gute Handwerksarbeit ist Gottesdienst. Sulaimān: der Wind, der in einem Monat eine Monatsreise zurücklegt, die Quelle aus geschmolzenem Kupfer, Dschinn, die Gebetsnischen, Bilder (nach der Erklärung der Gelehrten: in ihrer Scharia erlaubt) und Becken wie Teiche bauen. Dann der Auftrag 34:13 und die Todesszene 34:14: Sulaimān stirbt stehend, auf seinen Stab gestützt; die Dschinn arbeiten weiter, bis der Holzwurm den Stab zerfrisst und er fällt. „Hätten sie das Verborgene gekannt, wären sie nicht in der erniedrigenden Pein geblieben.“ As-Saʿdī: Eine doppelte Lektion – Allahs Macht über den Mächtigsten und die Entlarvung aller, die den Dschinn Zukunftswissen zuschreiben."},
 {vers: "Verse 15–21: das Volk von Sabaʾ", text: "„Esst von der Versorgung eures Herrn und seid Ihm dankbar: ein gutes Land und ein vergebender Herr“ (34:15) – das Rezept eines gesegneten Volkes. Doch sie wandten sich ab: Der Damm brach, die Gärten wurden zu Gestrüpp. „So vergalten Wir ihnen, weil sie undankbar waren – und vergelten Wir anders als dem Undankbaren?“ Dann ein zweiter Fehler: Zwischen ihnen und den gesegneten Städten lagen sichere Reisewege mit Raststationen – doch sie sagten: „Unser Herr, mach die Entfernungen zwischen unseren Reisen größer“ (34:19). Al-Qurṭubī: Sie waren der Sicherheit überdrüssig, wie die Kinder Isrāʾīl des Manna überdrüssig wurden. Wohlstand ohne Dank erzeugt Langeweile, Langeweile erzeugt Undank. Und 34:20: Iblīs fand seine Vermutung über sie bestätigt – sie folgten ihm."},
 {vers: "Verse 22–42: keine Fürsprecher ohne Erlaubnis", text: "Die Götzen besitzen „nicht das Gewicht eines Stäubchens in den Himmeln und auf der Erde“; Fürsprache nützt nur, wem Allah es erlaubt. 34:23 beschreibt den Schrecken der Engel, wenn Allah im Himmel einen Befehl spricht – „bis, wenn der Schrecken aus ihren Herzen gewichen ist, sie sagen: Was hat euer Herr gesagt? Sie sagen: Die Wahrheit“ (vgl. Sahih al-Buchari, Nr. 4800). Dann die Reichen und die Mächtigen: „Wir haben mehr Vermögen und Kinder, wir werden nicht bestraft“ (34:35). Antwort: „Nicht euer Vermögen und nicht eure Kinder bringen euch Uns näher, sondern nur, wer glaubt und rechtschaffen handelt“ (34:37). Und die Verführer und Verführten streiten in der Hölle: „Ihr wart es, die bei Tag und Nacht Ränke schmiedeten!“"},
 {vers: "Verse 43–54: der Aufruf zum Nachdenken", text: "„Sag: Ich ermahne euch nur zu einem: dass ihr für Allah aufsteht, zu zweit und einzeln, und dann nachdenkt: Euer Gefährte ist nicht besessen; er ist nur ein Warner vor einer strengen Strafe“ (34:46). Ibn Kathīr: Der Prophet ﷺ fordert kein blindes Folgen, sondern ehrliches Denken ohne Gruppendruck. „Ich habe von euch keinen Lohn verlangt – mein Lohn obliegt Allah“ (34:47). Dann das Ende: Die Leugner wollen am Tag der Strafe glauben, „doch wie sollten sie (den Glauben) von einem fernen Ort aus erlangen?“ – die Zeit zum Glauben war das Diesseits."}
],
ahadith: [
 {text: "Der Prophet ﷺ stand nachts, bis seine Füße anschwollen. Man sagte ihm: Dir ist doch vergeben. Er sagte: „Soll ich nicht ein dankbarer Diener sein?“", quelle: "Sahih al-Buchari, Nr. 4837; Sahih Muslim, Nr. 2819"},
 {text: "Wenn Allah im Himmel einen Befehl beschließt, schlagen die Engel aus Demut mit den Flügeln … „Was hat euer Herr gesagt?“ – „Die Wahrheit, und Er ist der Erhabene, der Große.“", quelle: "Sahih al-Buchari, Nr. 4800"},
 {text: "Farwa ibn Musaik fragte nach Sabaʾ: „Es war ein Mann, der zehn Söhne hatte …“", quelle: "Sunan at-Tirmidhī, Nr. 3222; hasan"},
 {text: "„Wie wunderbar ist die Sache des Gläubigen … Trifft ihn Gutes, dankt er, und es ist gut für ihn.“", quelle: "Sahih Muslim, Nr. 2999"}
],
hanafi: null,
umsetzung: [
 "Arbeite in Dankbarkeit (34:13): Mach deine Berufsarbeit ordentlich und mit guter Absicht – Dāwūds sauber gefertigte Panzerhemden waren Gottesdienst.",
 "Prüfe den Sabaʾ-Fehler bei dir (34:19): Wo bin ich einer Gabe überdrüssig geworden (Sicherheit, Familie, Gesundheit, Wohnung)? Langeweile mit Gaben ist der erste Schritt zum Undank.",
 "Mach das 34:46-Nachdenken: Nimm dir eine Glaubensfrage, die dich beschäftigt, und denk sie mit einem einzigen vertrauten Menschen oder allein durch – ohne Social Media, ohne Gruppendruck.",
 "Erinnere dich an 34:37: Nicht Kontostand und Kinderzahl bringen dich Allah näher, sondern Iman und gute Taten – ein guter Satz für jedes Familienfest mit Statusvergleich."
]
},

// ───────────────────────── Lektion 59: Az-Zumar ─────────────────────────
{
sure: 39, offb: 59, name: "Az-Zumar", arab: "سُورَةُ الزُّمَرِ", de: "Die Scharen", verse: 75, ort: "Mekka",
zeit: "Spätmekkanisch – die Sure der Aufrichtigkeit (Ichlāṣ) und der Hoffnung, kurz vor der ersten Auswanderung nach Abessinien",
kurz: "Az-Zumar ist die Sure des reinen Glaubens und der größten Hoffnung. Ihr Schlüsselwort ist Ichlāṣ: „Diene Allah, indem du Ihm die Religion aufrichtig darbringst“ – und sie entlarvt die Ausrede der Götzendiener: „Wir dienen ihnen nur, damit sie uns Allah näherbringen.“ Ihr berühmtester Vers ist der hoffnungsvollste des ganzen Korans: „Sag: O Meine Diener, die ihr gegen euch selbst maßlos gewesen seid, verzweifelt nicht an der Barmherzigkeit Allahs. Allah vergibt alle Sünden.“ Er wurde für Menschen herabgesandt, die gemordet und Unzucht begangen hatten und fragten, ob es für sie noch Rettung gebe. Am Ende ziehen die Menschen in Scharen (zumar) – die einen zur Hölle, die anderen zum Paradies, wo die Wächter sie mit Salām empfangen. Die Sure endet mit dem Satz: „Und es wird gesagt: Lob sei Allah, dem Herrn der Welten.“",
schluessel: {arab: "قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَىٰ أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ ۚ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا", ueb: "Sag: O Meine Diener, die ihr gegen euch selbst maßlos gewesen seid, verzweifelt nicht an der Barmherzigkeit Allahs. Allah vergibt gewiss alle Sünden.", ref: "39:53"},
kontext: ["Ibn ʿAbbās berichtet den Anlass von 39:53: Menschen aus dem Volk des Schirk, die viel getötet und viel Unzucht begangen hatten, kamen zum Propheten ﷺ und sagten: „Was du sagst und wozu du rufst, ist gut – wenn du uns nur sagen würdest, dass es für das, was wir getan haben, eine Sühne gibt.“ Da wurden 25:68–70 und 39:53 herabgesandt (Sahih al-Buchari, Nr. 4810; Sahih Muslim, Nr. 122). Der Vers ist also eine direkte Antwort auf die Frage: Ist es für mich zu spät?",
"Die Sure fällt in eine Zeit großen Drucks. 39:10 – „Allahs Erde ist weit“ – deuteten viele Gelehrte als Hinweis auf die Auswanderung nach Abessinien: Wer seinen Glauben an einem Ort nicht leben kann, darf gehen.",
"ʿĀʾischa berichtet, dass der Prophet ﷺ nicht schlief, bevor er Az-Zumar und Banī Isrāʾīl (Al-Isrāʾ) rezitiert hatte (at-Tirmidhī, Nr. 2920; hasan) – eine Sure für die Nacht, für das Gespräch mit sich selbst."],
asbab: [
 {text: "39:53: Götzendiener, die viel getötet und Unzucht begangen hatten, fragten nach einer Sühne – daraufhin kamen 25:68–70 und 39:53 herab.", quelle: "Sahih al-Buchari, Nr. 4810; Sahih Muslim, Nr. 122"},
 {text: "39:67 („Sie haben Allah nicht gebührend eingeschätzt“): Ein jüdischer Gelehrter sagte, Allah lege am Jüngsten Tag die Himmel auf einen Finger, die Erden auf einen Finger … Der Prophet ﷺ lachte zustimmend und rezitierte den Vers.", quelle: "Sahih al-Buchari, Nr. 4811; Sahih Muslim, Nr. 2786"}
],
begriffe: [
 {arab: "مُخْلِصًا لَّهُ الدِّين", tr: "muchliṣan lahu d-dīn", wurzel: "ch-l-ṣ", erkl: "„Ihm die Religion aufrichtig darbringend“ (39:2, 11, 14) – das Leitmotiv der Sure. Ichlāṣ heißt: alles nur für Allah, ohne Nebenabsicht. Vgl. Lektion 22 (Al-Ichlāṣ)."},
 {arab: "زُلْفَىٰ", tr: "zulfā", wurzel: "z-l-f", erkl: "„Nähe“ (39:3): „Wir dienen ihnen nur, damit sie uns Allah näherbringen.“ Die klassische Ausrede jedes Vermittler-Kults – die Sure nennt sie Lüge. Zu Allah braucht es keine Zwischenstation."},
 {arab: "أَسْرَفُوا", tr: "asrafū", wurzel: "s-r-f", erkl: "„Sie waren maßlos“ (39:53) – hier: maßlos im Sündigen. Allah nennt sie trotzdem „Meine Diener“ (yā ʿibādī). Die Anrede selbst ist schon die halbe Vergebung."},
 {arab: "لَا تَقْنَطُوا", tr: "lā taqnaṭū", wurzel: "q-n-ṭ", erkl: "„Verzweifelt nicht“ – qunūṭ ist die völlige Hoffnungslosigkeit. Im Koran ist sie eine Eigenschaft der Irregehenden (15:56). Verzweiflung an Allahs Vergebung ist selbst eine Sünde."},
 {arab: "زُمَر", tr: "zumar", wurzel: "z-m-r", erkl: "„Scharen, Gruppen“ (39:71, 73) – die Menschen ziehen am Jüngsten Tag in Gruppen, sortiert nach ihren Taten. Im Paradies öffnen sich die Tore bereits, bevor sie ankommen (39:73: wa-futiḥat – „und seine Tore sind geöffnet“)."},
 {arab: "مَقَالِيد", tr: "maqālīd", wurzel: "q-l-d", erkl: "„Die Schlüssel“ (39:63): „Ihm gehören die Schlüssel der Himmel und der Erde.“ Wer die Schlüssel hat, entscheidet über jede Tür – auch über die Tür der Vergebung."}
],
tafsir: [
 {vers: "Verse 1–21: Ichlāṣ und die zwei Arten Menschen", text: "„Gehört nicht Allah allein die aufrichtige Religion?“ (39:3). Die Sure widerlegt die Vermittler-Ausrede und zeigt Allah als Schöpfer, der „die Nacht um den Tag wickelt“ (39:5) und den Menschen in drei Finsternissen im Mutterleib formt (39:6). Dann ein Porträt: der Mensch, der in Not betet und im Wohlstand vergisst (39:8). Gegenbild 39:9: „Ist etwa der, der in den Stunden der Nacht demütig ist, sich niederwirft und steht, das Jenseits fürchtet und auf die Barmherzigkeit seines Herrn hofft …? Sag: Sind etwa die, die wissen, und die, die nicht wissen, gleich?“ As-Saʿdī: Wissen im Koran ist Wissen, das zur Nachtanbetung führt. Dann 39:10: „Den Geduldigen wird ihr Lohn ohne Abrechnung voll gegeben.“ Und 39:18: „die das Wort hören und dem Besten davon folgen“ – die Kunst, zwischen gut und besser zu unterscheiden."},
 {vers: "Verse 22–41: das Herz, das sich öffnet", text: "„Ist etwa der, dessen Brust Allah für den Islam geweitet hat, sodass er sich auf einem Licht von seinem Herrn befindet …? Wehe denen, deren Herzen gegen das Gedenken Allahs verhärtet sind!“ (39:22, vgl. 94:1 in Lektion 12). 39:23 beschreibt die Wirkung des Korans auf die Gläubigen: „Davon erschauert die Haut derer, die ihren Herrn fürchten; dann werden ihre Haut und ihre Herzen weich beim Gedenken Allahs.“ Ibn Kathīr: Das ist das Kennzeichen der Gefährten beim Hören – Erschauern und Weichwerden, nicht Ohnmacht oder Geschrei. 39:30 dann ein ernster Satz an den Propheten ﷺ: „Du wirst sterben, und sie werden sterben“ – Abū Bakr rezitierte ihn am Todestag des Propheten ﷺ zusammen mit 3:144."},
 {vers: "Verse 42–52: Schlaf, Tod und die Fürsprecher", text: "„Allah beruft die Seelen zur Zeit ihres Todes ab und auch die, die nicht gestorben sind, in ihrem Schlaf“ (39:42) – der Schlaf als kleiner Tod; darum das Bittgebet beim Aufwachen: „Lob sei Allah, Der uns lebendig gemacht hat, nachdem Er uns sterben ließ“ (Sahih al-Buchari, Nr. 6312). Dann: Die Herzen der Götzendiener verkrampfen sich, wenn Allah allein erwähnt wird, und freuen sich, wenn andere erwähnt werden (39:45) – ein Test für jedes Herz."},
 {vers: "Verse 53–63: der Hoffnungsvers", text: "„O Meine Diener, die ihr gegen euch selbst maßlos gewesen seid …“ – Der Vers enthält mehrere Ermutigungen: Allah nennt Sünder „Meine Diener“; Er sagt „gegen euch selbst“ – die Sünde schadet dem Sünder, nicht Allah; Er verbietet die Verzweiflung; Er sagt „alle Sünden“ (dschamīʿan) – keine Ausnahme bei Tauba, auch nicht Schirk und Mord, wie der Anlass zeigt. Ibn Kathīr betont den Zusammenhang mit dem nächsten Vers: „Und wendet euch eurem Herrn reuig zu und ergebt euch Ihm, bevor die Strafe über euch kommt“ (39:54). Hoffnung ist also kein Freibrief, sondern eine offene Tür – mit einer Frist. Der Hadith vom Mann, der 99 Menschen tötete und dann einen Gelehrten fragte, zeigt dasselbe: Er machte sich auf den Weg zur Tauba und starb unterwegs – und die Engel der Barmherzigkeit nahmen ihn (Sahih al-Buchari, Nr. 3470; Sahih Muslim, Nr. 2766). Die Sure warnt dann vor dem dreifachen Bedauern am Jüngsten Tag: „Wehe mir, was ich gegenüber Allah versäumt habe!“ – „Hätte Allah mich nur rechtgeleitet!“ – „Hätte ich nur noch eine Rückkehr!“ (39:56–58)."},
 {vers: "Verse 64–75: Posaune, Licht und die Scharen", text: "39:65 warnt selbst den Propheten ﷺ: „Wenn du (Allah) etwas beigesellst, werden deine Werke hinfällig“ – eine Lehre für alle: Schirk zerstört alles. 39:67: die Himmel zusammengerollt in Seiner Rechten. Der erste Posaunenstoß, alle sterben, außer wen Allah will; der zweite, alle stehen auf (39:68; zwischen beiden liegt „vierzig“, Sahih al-Buchari, Nr. 4814). „Die Erde erstrahlt im Licht ihres Herrn, das Buch wird hingelegt, die Propheten und Zeugen werden gebracht“ (39:69). Dann die Scharen: Zur Hölle getrieben, die Tore öffnen sich bei ihrer Ankunft; zum Paradies geführt – die Tore sind schon offen, und die Wächter sagen: „Friede sei auf euch, ihr seid gut gewesen.“ Die Engel umkreisen den Thron, und „es wird gesagt: Lob sei Allah, dem Herrn der Welten“ – das letzte Wort der Schöpfung ist Lob."}
],
ahadith: [
 {text: "Ibn ʿAbbās: Götzendiener, die viel getötet und Unzucht begangen hatten, fragten nach einer Sühne – da kam 39:53 herab.", quelle: "Sahih al-Buchari, Nr. 4810; Sahih Muslim, Nr. 122"},
 {text: "Der Mann, der 99 Menschen tötete, dann den hundertsten, und sich dann zur Tauba auf den Weg machte – die Engel der Barmherzigkeit nahmen ihn.", quelle: "Sahih al-Buchari, Nr. 3470; Sahih Muslim, Nr. 2766"},
 {text: "Hadith Qudsi: „O Sohn Ādams, solange du Mich anrufst und auf Mich hoffst, vergebe Ich dir, was von dir war, und kümmere Mich nicht darum … Kämest du zu Mir mit Sünden fast so groß wie die Erde und begegnetest Mir, ohne Mir etwas beizugesellen, käme Ich zu dir mit fast ebenso großer Vergebung.“", quelle: "Sunan at-Tirmidhī, Nr. 3540; hasan"},
 {text: "ʿĀʾischa: Der Prophet ﷺ schlief nicht, bevor er Az-Zumar und Banī Isrāʾīl rezitiert hatte.", quelle: "Sunan at-Tirmidhī, Nr. 2920; hasan"}
],
hanafi: null,
umsetzung: [
 "Lerne 39:53 auswendig und gib ihn weiter an jeden, der denkt, er sei ‚zu weit weg' – mit der Geschichte des Anlasses: Er kam für Mörder und Ehebrecher, die umkehren wollten.",
 "Kombiniere Hoffnung mit Handeln (39:54): Mach heute eine konkrete Tauba – Istiġfār, ein Unrecht wiedergutmachen, eine Sünde beenden. Die Tür ist offen, aber nicht für immer.",
 "Sprich beim Aufwachen das Bittgebet aus Buchari 6312 (al-ḥamdu lillāhi lladhī aḥyānā baʿda mā amātanā wa-ilaihi n-nuschūr) – jeder Morgen ist eine kleine Auferstehung (39:42).",
 "Prüfe dein Herz mit 39:45: Freust du dich, wenn Allah allein erwähnt wird? Oder lebst du erst auf, wenn es um Menschen, Fußball oder Geld geht?"
]
},

// ───────────────────────── Lektion 60: Ġāfir ─────────────────────────
{
sure: 40, offb: 60, name: "Ġāfir", arab: "سُورَةُ غَافِرٍ", de: "Der Vergebende", verse: 85, ort: "Mekka",
zeit: "Spätmekkanisch – als die Quraisch den Propheten ﷺ angriffen und Abū Bakr ihn verteidigte",
kurz: "Die erste der sieben Ḥā-Mīm-Suren (40–46), die mit den Buchstaben Ḥā Mīm beginnen. Ihr Held ist ein unbekannter Mann: ein gläubiger Angehöriger aus dem Haus Pharaos, der seinen Glauben verbarg. Als Pharao Mūsā töten will, steht er auf und sagt: „Wollt ihr einen Mann töten, weil er sagt: Mein Herr ist Allah?“ Mit klugen Argumenten, Geduld und großer Liebe zu seinem Volk spricht er zu ihnen – und am Ende sagt er: „Ich überlasse meine Angelegenheit Allah.“ Allah schützt ihn vor ihren Ränken. Die Sure beginnt mit Allahs Namen „der die Sünde vergibt und die Reue annimmt“ und mit den Engeln, die den Thron tragen und für die Gläubigen um Vergebung bitten. Und sie enthält einen der wichtigsten Verse über das Bittgebet: „Euer Herr sagt: Ruft Mich an, so erhöre Ich euch.“",
schluessel: {arab: "وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ", ueb: "Und euer Herr sagt: Ruft Mich an, so erhöre Ich euch.", ref: "40:60"},
kontext: ["Die Szene des gläubigen Mannes aus dem Haus Pharaos wiederholte sich in Mekka: ʿUrwa ibn az-Zubair fragte ʿAbdullāh ibn ʿAmr nach dem Schlimmsten, was die Götzendiener dem Propheten ﷺ angetan hatten. Er erzählte: Der Prophet ﷺ betete im Hof der Kaaba, da kam ʿUqba ibn Abī Muʿaiṭ, legte ihm sein Gewand um den Hals und würgte ihn heftig. Abū Bakr kam, packte ʿUqba an der Schulter, stieß ihn weg und sagte: „Wollt ihr einen Mann töten, weil er sagt: Mein Herr ist Allah – wo er doch mit klaren Beweisen von eurem Herrn zu euch gekommen ist?“ (Sahih al-Buchari, Nr. 3678) – mit genau den Worten von 40:28.",
"Die Ḥā-Mīm-Suren (40–46) bilden eine Familie: Alle sind mekkanisch, alle beginnen mit Ḥā Mīm und sprechen über die Herabsendung des Buches. Ibn Masʿūd nannte sie die „Schmuckstücke des Korans“ (Tafsir-Bericht, bei Ibn Kathīr zitiert).",
"Der Name „Ġāfir“ (der Vergebende) kommt aus dem dritten Vers. Eine andere Bezeichnung der Sure ist „al-Muʾmin“ (der Gläubige) – nach dem gläubigen Mann aus dem Haus Pharaos."],
asbab: [
 {text: "Die Worte von 40:28 („Wollt ihr einen Mann töten, weil er sagt: Mein Herr ist Allah?“) sprach Abū Bakr, als er ʿUqba ibn Abī Muʿaiṭ vom Propheten ﷺ wegstieß, der ihn würgte.", quelle: "Sahih al-Buchari, Nr. 3678 (vgl. 4815)"}
],
begriffe: [
 {arab: "حمٓ", tr: "Ḥā Mīm", wurzel: "–", erkl: "Zwei der geheimnisvollen Einzelbuchstaben (vgl. Lektion 2). Sie stehen am Anfang von sieben aufeinanderfolgenden Suren (40–46), den „Ḥawāmīm“."},
 {arab: "غَافِرِ الذَّنبِ وَقَابِلِ التَّوْبِ", tr: "ġāfir adh-dhanb wa-qābil at-taub", wurzel: "ġ-f-r / t-w-b", erkl: "„Der die Sünde vergibt und die Reue annimmt“ (40:3) – direkt danach: „streng im Bestrafen, voller Wohltat“. Wieder die Balance von Hoffnung und Ehrfurcht (vgl. Lektion 27)."},
 {arab: "حَمَلَةُ الْعَرْش", tr: "ḥamalat al-ʿarsch", wurzel: "ḥ-m-l", erkl: "„Die Träger des Thrones“ (40:7) – die mächtigsten Engel bitten für die Gläubigen um Vergebung: „Unser Herr, Du umfasst alles mit Barmherzigkeit und Wissen, so vergib denen, die bereuen.“ Du hast Fürsprecher, von denen du nichts weißt."},
 {arab: "يَكْتُمُ إِيمَانَهُ", tr: "yaktumu īmānahu", wurzel: "k-t-m", erkl: "„Der seinen Glauben verborgen hielt“ (40:28) – der gläubige Mann im Haus Pharaos. Verbergen aus Schutz ist kein Verrat am Glauben; als es darauf ankam, sprach er offen."},
 {arab: "أُفَوِّضُ أَمْرِي إِلَى اللَّهِ", tr: "ufawwiḍu amrī ilā llāh", wurzel: "f-w-ḍ", erkl: "„Ich überlasse meine Angelegenheit Allah“ (40:44) – tafwīḍ: die völlige Übergabe. Nachdem er alles gesagt hatte, was er sagen konnte, übergab er den Rest. Das ist Tawakkul in Reinform."},
 {arab: "ادْعُونِي", tr: "udʿūnī", wurzel: "d-ʿ-w", erkl: "„Ruft Mich an!“ (40:60) – direkt danach: „Diejenigen, die zu hochmütig sind, Mir zu dienen, werden Dschahannam erniedrigt betreten.“ Wer nicht bittet, gilt als hochmütig – Duʿā ist ʿIbāda."}
],
tafsir: [
 {vers: "Verse 1–22: Vergebung und Engel", text: "Nach den Namen Allahs (40:2–3) die Warnung: Nur die Ungläubigen streiten über Allahs Zeichen – „lass dich nicht von ihrem Umherziehen in den Ländern täuschen“ (40:4), Erfolg und Reisefreiheit sind kein Beweis für Wahrheit. Dann die Engel am Thron (40:7–9): Sie bitten um Vergebung, um Schutz vor der Hölle, um das Paradies für die Gläubigen „und die Rechtschaffenen unter ihren Vätern, Gattinnen und Nachkommen“. As-Saʿdī: Allah hat die Gläubigen mit Engel-Fürsprache umgeben, bevor sie selbst um etwas gebeten haben. Dann der Tag des Gerichts: „Wem gehört heute die Herrschaft? – Allah, dem Einen, dem Allbezwinger“ (40:16)."},
 {vers: "Verse 23–46: der gläubige Mann aus Pharaos Haus", text: "Pharao sagt: „Lasst mich Mūsā töten – ich fürchte, er ändert eure Religion oder stiftet Unheil im Land“ (40:26). Ibn Kathīr: Der Tyrann gibt sich als Beschützer der Religion und der Ordnung aus. Dann der gläubige Mann mit einer Argumentation, die man in jedem Daʿwa-Kurs lehren sollte: (1) Fairness: „Wenn er ein Lügner ist, trägt er seine Lüge selbst; wenn er die Wahrheit sagt, trifft euch etwas von dem, was er androht“ (40:28). (2) Gemeinsame Sorge: „Mein Volk, heute habt ihr die Macht – doch wer hilft uns gegen Allahs Strafe?“ (3) Geschichte: das Schicksal von Nūḥ, ʿĀd und Ṯamūd. (4) Erinnerung an Yūsuf, den sie auch abgelehnt hatten. (5) Jenseits: „Mein Volk, dieses diesseitige Leben ist nur ein Genuss, das Jenseits ist die bleibende Wohnstätte“ (40:39). (6) Klarer Kontrast: „Ich rufe euch zur Rettung, und ihr ruft mich zum Feuer“ (40:41). Dann tafwīḍ (40:44) – „und Allah bewahrte ihn vor den bösen Ränken“. Pharao befiehlt Hāmān einen Turm zu bauen, um nach Mūsās Gott zu schauen (40:36–37) – der Spott des Mächtigen. 40:46: Pharaos Leute werden „morgens und abends dem Feuer vorgeführt“ – ein Beleg der Gelehrten für die Strafe im Grab (Barzach)."},
 {vers: "Verse 47–60: Streit in der Hölle und das Duʿā", text: "Die Schwachen sagen in der Hölle zu den Hochmütigen: „Wir waren eure Gefolgschaft – nehmt ihr uns etwas vom Feuer ab?“ (40:47). Antwort: „Wir sind alle darin.“ Dann die Zusage: „Wir helfen Unseren Gesandten und denen, die glauben, im diesseitigen Leben und am Tag, an dem die Zeugen auftreten“ (40:51). Und dann 40:60. Der Prophet ﷺ rezitierte diesen Vers, nachdem er sagte: „Das Bittgebet ist der Gottesdienst (ad-duʿāʾu huwa l-ʿibāda)“ (Abū Dāwūd, Nr. 1479; at-Tirmidhī, Nr. 2969; sahih). Al-Qurṭubī: Das Bitten ist das Eingeständnis der eigenen Bedürftigkeit – darum ist Nicht-Bitten Hochmut."},
 {vers: "Verse 61–85: Zeichen und das Ende der Ausreden", text: "Nacht zur Ruhe, Tag zum Sehen, Erde als fester Grund, Himmel als Bau, „und Er hat euch gestaltet und eure Gestalten schön gemacht“ (40:64). Dann die Lebensstufen: Staub, Tropfen, Anhängsel, Kind, Erwachsener, Greis – „manche von euch werden vorher abberufen“ (40:67). Die Sure endet mit einem ernsten Gesetz: Als die früheren Völker die Strafe sahen, sagten sie: „Wir glauben an Allah allein!“ – „doch ihr Glaube nützte ihnen nichts mehr, als sie Unsere Strafe sahen“ (40:84–85). Die Tauba hat eine Frist: bevor der Tod oder die Strafe sichtbar wird (vgl. 39:54 in Lektion 59)."}
],
ahadith: [
 {text: "ʿAbdullāh ibn ʿAmr: ʿUqba ibn Abī Muʿaiṭ würgte den Propheten ﷺ mit seinem Gewand; Abū Bakr stieß ihn weg und sagte: „Wollt ihr einen Mann töten, weil er sagt: Mein Herr ist Allah?“", quelle: "Sahih al-Buchari, Nr. 3678"},
 {text: "„Das Bittgebet ist der Gottesdienst“ – dann rezitierte er: „Euer Herr sagt: Ruft Mich an, so erhöre Ich euch.“", quelle: "Sunan Abū Dāwūd, Nr. 1479; at-Tirmidhī, Nr. 2969; sahih"},
 {text: "„Allah nimmt die Reue des Dieners an, solange er nicht im Todesröcheln liegt.“ – zu 40:85.", quelle: "Sunan at-Tirmidhī, Nr. 3537; hasan"},
 {text: "„Euer Herr ist schamhaft und großzügig – Er schämt sich, die Hände Seines Dieners leer zurückzuweisen, wenn er sie zu Ihm erhebt.“", quelle: "Sunan Abū Dāwūd, Nr. 1488; at-Tirmidhī, Nr. 3556; sahih"}
],
hanafi: null,
umsetzung: [
 "Lerne die Argumentation des gläubigen Mannes (40:28–44) für Gespräche: Fairness, gemeinsame Sorge, Geschichte, Jenseits, klarer Kontrast – und am Ende tafwīḍ: Du überlässt das Ergebnis Allah.",
 "Mach Duʿā zu deiner Haltung (40:60): Bitte Allah auch um Kleinigkeiten – Parkplatz, Konzentration, ein gutes Gespräch. Wer viel bittet, ist demütig.",
 "Verteidige die Schwachen wie Abū Bakr: Wenn jemand wegen seines Glaubens angegriffen wird – auch verbal, auch online –, steh auf und sag etwas.",
 "Denk an die Thronträger (40:7): Du bist nicht allein – die mächtigsten Engel bitten für dich, solange du bereust und Seinem Weg folgst."
]
},

// ───────────────────────── Lektion 61: Fuṣṣilat ─────────────────────────
{
sure: 41, offb: 61, name: "Fuṣṣilat", arab: "سُورَةُ فُصِّلَتْ", de: "Ausführlich dargelegt", verse: 54, ort: "Mekka",
zeit: "Spätmekkanisch – die Sure, die ʿUtba ibn Rabīʿa, einen Wortführer der Quraisch, verstummen ließ",
kurz: "Die Quraisch schickten ʿUtba ibn Rabīʿa, einen ihrer klügsten Männer, mit einem Angebot zum Propheten ﷺ: Geld, Herrschaft, Ärzte – alles, wenn er nur aufhört. Der Prophet ﷺ hörte ihm in Ruhe zu und fragte: „Bist du fertig, Abū l-Walīd?“ Dann rezitierte er diese Sure. ʿUtba hörte zu, die Hände hinter dem Rücken aufgestützt, bis zum Vers über die Strafe von ʿĀd und Ṯamūd – da legte er seine Hand auf den Mund des Propheten ﷺ und bat ihn, aufzuhören. Er kehrte zu den Quraisch zurück mit einem anderen Gesicht: „Ich habe Worte gehört, wie ich nie welche gehört habe – weder Dichtung noch Zauberei.“ Fuṣṣilat enthält die Szene, in der Haut, Augen und Ohren gegen den Menschen aussagen, die Verheißung an die, die sagen „Unser Herr ist Allah“ und dann standhaft bleiben, und die Goldregel für jeden Konflikt: „Wehre (das Böse) mit dem ab, was besser ist – dann wird der, mit dem du in Feindschaft warst, wie ein enger Freund.“",
schluessel: {arab: "ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ فَإِذَا الَّذِي بَيْنَكَ وَبَيْنَهُ عَدَاوَةٌ كَأَنَّهُ وَلِيٌّ حَمِيمٌ", ueb: "Wehre (das Böse) mit dem ab, was besser ist – dann wird der, zwischen dem und dir Feindschaft war, wie ein enger Freund.", ref: "41:34"},
kontext: ["Die Geschichte von ʿUtba ibn Rabīʿa wird in der Sīra (Ibn Isḥāq) und in Hadith-Sammlungen (u. a. Abū Yaʿlā, al-Baihaqī in Dalāʾil an-Nubuwwa) überliefert; die Gelehrten stufen sie als gut belegt ein, auch wenn sie nicht bei Buchari und Muslim steht. ʿUtba sagte danach zu den Quraisch: „Lasst diesen Mann in Ruhe. Wenn die Araber ihn besiegen, seid ihr ihn los; wenn er siegt, ist seine Herrschaft eure Herrschaft.“ Sie antworteten: „Er hat dich mit seiner Zunge verzaubert.“",
"Die Sure dokumentiert die Strategie der Gegner in 41:26: „Hört nicht auf diesen Koran und macht Lärm dabei, auf dass ihr siegen möget!“ – Lärm statt Argument, Übertönen statt Zuhören. Eine Taktik, die es bis heute gibt.",
"Fuṣṣilat ist die zweite der Ḥā-Mīm-Suren. Ihr Name „ausführlich dargelegt“ (41:3) beschreibt den Koran: Seine Verse sind klar gegliedert, „ein arabischer Koran für Leute, die Wissen haben“."],
asbab: [
 {text: "Die Rezitation der Sure vor ʿUtba ibn Rabīʿa, der mit einem Angebot der Quraisch kam und erschüttert zurückkehrte.", quelle: "Sīra Ibn Isḥāq/Ibn Hischām; al-Baihaqī, Dalāʾil an-Nubuwwa; Abū Yaʿlā (von den Gelehrten als gut belegt eingestuft)"},
 {text: "Zu 41:22–23: Drei Männer saßen an der Kaaba; einer fragte: „Meint ihr, Allah hört, was wir sagen?“ – „Er hört, wenn wir laut sprechen, nicht aber, wenn wir leise sprechen.“ Ein anderer: „Wenn Er etwas hört, hört Er alles.“ Darauf kam der Vers herab: „Ihr habt euch nicht davor versteckt, dass euer Gehör, eure Augen und eure Haut gegen euch zeugen …“", quelle: "Sahih al-Buchari, Nr. 4816; Sahih Muslim, Nr. 2775"}
],
begriffe: [
 {arab: "فُصِّلَتْ", tr: "fuṣṣilat", wurzel: "f-ṣ-l", erkl: "„Ausführlich dargelegt, klar gegliedert“ (41:3) – dieselbe Wurzel wie faṣl (Entscheidung, Lektion 36): Der Koran trennt und erklärt."},
 {arab: "وَالْغَوْا فِيهِ", tr: "wa-lġau fīhi", wurzel: "l-ġ-w", erkl: "„Und macht Lärm dabei“ (41:26) – die Taktik der Quraisch, den Koran zu übertönen. Laġw ist leeres, störendes Gerede (vgl. 25:72 in Lektion 42)."},
 {arab: "اسْتَقَامُوا", tr: "istaqāmū", wurzel: "q-w-m", erkl: "„Sie blieben standhaft/geradlinig“ (41:30): „Diejenigen, die sagen: Unser Herr ist Allah, und dann standhaft bleiben – auf sie kommen die Engel herab: Fürchtet euch nicht und seid nicht traurig.“ Istiqāma ist der Iman über die Zeit."},
 {arab: "بِالَّتِي هِيَ أَحْسَنُ", tr: "bi-llatī hiya aḥsan", wurzel: "ḥ-s-n", erkl: "„Mit dem, was besser ist“ (41:34) – nicht nur ‚gut', sondern die bessere Antwort: Auf Zorn mit Geduld, auf Unwissenheit mit Nachsicht, auf Kränkung mit Vergebung (Ibn ʿAbbās)."},
 {arab: "ذُو حَظٍّ عَظِيمٍ", tr: "dhū ḥaẓẓin ʿaẓīm", wurzel: "ḥ-ẓ-ẓ", erkl: "„Einer, der ein gewaltiges Glück hat“ (41:35): „Dies wird nur denen gewährt, die geduldig sind; und es wird nur dem gewährt, der ein gewaltiges Glück hat.“ Die Fähigkeit, Böses mit Gutem zu beantworten, ist ein Geschenk."},
 {arab: "نَزْغ", tr: "nazġ", wurzel: "n-z-ġ", erkl: "„Ein Anstacheln“ (41:36): „Wenn dich vom Satan ein Anstacheln trifft, dann suche Zuflucht bei Allah.“ Im Streit ist der Satan der dritte Gesprächspartner (vgl. Lektion 21)."}
],
tafsir: [
 {vers: "Verse 1–25: das klare Buch, die Schöpfung und die Zeugen", text: "Der Koran als „frohe Botschaft und Warnung – doch die meisten wenden sich ab und hören nicht. Sie sagen: Unsere Herzen sind verhüllt …“ (41:4–5). Der Prophet ﷺ antwortet mit Demut: „Ich bin nur ein Mensch wie ihr; mir wird offenbart, dass euer Gott ein einziger Gott ist“ (41:6). Dann die Schöpfung von Erde und Himmel in Tagen (41:9–12) und der Satz: „Kommt beide, willig oder widerwillig! Sie sagten: Wir kommen willig“ – die ganze Schöpfung gehorcht; nur der Mensch zögert. Bei 41:13 stoppte ʿUtba den Propheten ﷺ: die Warnung vor einem Donnerschlag wie dem von ʿĀd und Ṯamūd. Dann die Zeugen-Szene (41:19–23): Die Feinde Allahs werden zum Feuer versammelt, und „ihr Gehör, ihre Augen und ihre Haut legen Zeugnis gegen sie ab“. Sie fragen ihre Haut: „Warum zeugt ihr gegen uns?“ – „Allah hat uns sprechen lassen, Der alles sprechen lässt.“ Ibn Kathīr: Der Körper, den du für Sünden benutzt, ist Allahs Leihgabe und wird zum Zeugen."},
 {vers: "Verse 26–36: Lärm, Standhaftigkeit und die beste Antwort", text: "Die Lärm-Taktik (41:26) und das Gegenbild: Die Standhaften (41:30–32), zu denen die Engel herabkommen – nach den Mufassirūn beim Tod, im Grab und bei der Auferstehung – mit drei Botschaften: keine Furcht vor dem, was kommt, keine Trauer über das, was war, frohe Botschaft vom Paradies. „Wir sind eure Schutzfreunde im diesseitigen Leben und im Jenseits.“ Dann 41:33: „Wer spricht schöner als jemand, der zu Allah ruft, Gutes tut und sagt: Ich gehöre zu den Muslimen?“ – das Lob des Dāʿī. Und 41:34–36: die beste Antwort auf das Böse. Ibn ʿAbbās erklärte: Allah befiehlt den Gläubigen Geduld beim Zorn, Nachsicht bei der Unwissenheit und Vergebung bei der Kränkung; wenn sie das tun, schützt Allah sie vor dem Satan und ihre Feinde unterwerfen sich ihnen, „als wären sie enge Freunde“ (Tafsir-Bericht bei aṭ-Ṭabarī)."},
 {vers: "Verse 37–44: Sonne, Mond und die Sadschda", text: "„Zu Seinen Zeichen gehören die Nacht und der Tag, die Sonne und der Mond. Werft euch nicht vor der Sonne nieder und nicht vor dem Mond, sondern werft euch vor Allah nieder, Der sie erschaffen hat“ (41:37). Und 41:38: „Wenn sie zu hochmütig sind – diejenigen, die bei deinem Herrn sind, preisen Ihn Nacht und Tag, und sie werden nicht müde.“ Hier ist die Tilāwa-Sadschda. Dann das Zeichen der toten Erde, die sich bewegt und anschwillt, wenn Regen fällt (41:39), und die Garantie für den Koran: „Falsches kommt nicht an ihn heran, weder von vorn noch von hinten“ (41:42). 41:44: „Für die, die glauben, ist er Rechtleitung und Heilung (schifāʾ).“"},
 {vers: "Verse 45–54: der Mensch und die Zeichen", text: "Ein psychologisches Porträt: „Der Mensch wird nicht müde, um Gutes zu bitten; doch wenn ihn Böses trifft, ist er verzweifelt und hoffnungslos“ (41:49). Und: Wenn es ihm gut geht, sagt er: „Das steht mir zu“ (41:50); in der Not betet er lang und breit (41:51). Das Ende ist eine Zusage, die über Mekka hinausreicht: „Wir werden ihnen Unsere Zeichen an den Horizonten und in ihnen selbst zeigen, bis ihnen klar wird, dass es die Wahrheit ist“ (41:53). As-Saʿdī: Jede Entdeckung im Weltall und im menschlichen Körper erfüllt diesen Vers ein Stück weiter."}
],
ahadith: [
 {text: "Drei Männer an der Kaaba fragten, ob Allah ihr leises Reden hört – darauf kam 41:22 herab.", quelle: "Sahih al-Buchari, Nr. 4816; Sahih Muslim, Nr. 2775"},
 {text: "Sufyān ibn ʿAbdillāh bat: „Sag mir im Islam ein Wort, nach dem ich niemanden mehr fragen muss.“ Er sagte: „Sag: Ich glaube an Allah – dann bleib standhaft (thumma staqim).“", quelle: "Sahih Muslim, Nr. 38"},
 {text: "„Der Starke ist nicht der, der im Ringkampf siegt; der Starke ist der, der sich im Zorn beherrscht.“ – zu 41:34.", quelle: "Sahih al-Buchari, Nr. 6114; Sahih Muslim, Nr. 2609"},
 {text: "„Allah hat keinem Diener wegen einer Vergebung etwas anderes vermehrt als Ehre.“", quelle: "Sahih Muslim, Nr. 2588"}
],
hanafi: "In Fuṣṣilat liegt eine der 14 Tilāwa-Sadschdas. Hanafitisch ist sie wādschib für Rezitierende und Hörende – und die Schule setzt sie bei Vers 38 („… und sie werden nicht müde“), nicht bei Vers 37, wie es die Schāfiʿiten und Mālikiten tun. Die Begründung: Erst mit Vers 38 ist der Gedanke des Verses vollständig. Wer hanafitisch liest, rezitiert also Vers 38 zu Ende und macht dann die Niederwerfung. Damit kennst du jetzt fünf Sadschda-Verse: 7:206, 38:24, 41:38, 53:62, 96:19.",
umsetzung: [
 "Wende 41:34 in deinem schwierigsten Konflikt an: Antworte auf eine Kränkung diese Woche bewusst mit etwas Besserem – einem Geschenk, einem Gruß, einer Hilfe. Beobachte, was passiert.",
 "Lerne den Hadith von Sufyān (Muslim 38) auswendig: āmantu billāh, thumma staqim – das kürzeste Lebensprogramm des Islam.",
 "Wenn dich im Streit Wut packt (41:36): sofort aʿūdhu billāhi mina sch-schaiṭāni r-radschīm sagen, die Stellung wechseln, Wudū machen.",
 "Sprich bei 41:38 die Tilāwa-Sadschda (hanafitisch wādschib) – nach Vers 38, nicht nach 37.",
 "Lies 41:53 als Einladung: Wenn du von einer wissenschaftlichen Entdeckung liest, sag subḥānallāh – du siehst ein Zeichen „an den Horizonten oder in dir selbst“."
]
},

// ───────────────────────── Lektion 62: Asch-Schūrā ─────────────────────────
{
sure: 42, offb: 62, name: "Asch-Schūrā", arab: "سُورَةُ الشُّورَىٰ", de: "Die Beratung", verse: 53, ort: "Mekka",
zeit: "Spätmekkanisch – die Sure, die die Gemeinschaftsordnung der Gläubigen beschreibt, noch bevor es einen Staat gab",
kurz: "Asch-Schūrā zeigt, wie eine gläubige Gemeinschaft aussieht – und das in Mekka, als die Muslime noch eine verfolgte Minderheit waren. Ihr berühmtester Vers über Allah lautet: „Nichts ist Ihm gleich, und Er ist der Allhörende, der Allsehende.“ Sie erklärt, dass alle Propheten dieselbe Religion brachten – Nūḥ, Ibrāhīm, Mūsā, ʿĪsā und Muhammad ﷺ – mit dem Auftrag: „Haltet die Religion aufrecht und spaltet euch nicht darin.“ Und sie beschreibt die Gläubigen: Sie vertrauen auf Allah, meiden schwere Sünden, vergeben im Zorn, verrichten das Gebet, „ihre Angelegenheiten regeln sie durch Beratung untereinander“, geben aus und wehren sich gegen Unrecht – doch „wer vergibt und Frieden stiftet, dessen Lohn obliegt Allah“.",
schluessel: {arab: "لَيْسَ كَمِثْلِهِ شَيْءٌ ۖ وَهُوَ السَّمِيعُ الْبَصِيرُ", ueb: "Nichts ist Ihm gleich; und Er ist der Allhörende, der Allsehende.", ref: "42:11"},
kontext: ["Die Sure ist die dritte der Ḥā-Mīm-Suren und trägt zusätzlich die Buchstaben ʿAin Sīn Qāf. Sie fällt in die Zeit, in der die Muslime in Mekka eine kleine Gemeinschaft waren – und doch schon die Grundzüge ihrer Ordnung erhielten: Beratung (schūrā), Gebet, Spenden, Vergebung, Gerechtigkeit. Die Gelehrten betonen: Schūrā wird hier in einem Atemzug mit dem Gebet genannt (42:38) – sie ist keine politische Technik, sondern ein Teil des Glaubens.",
"Zur Zeit der Offenbarung lebten die Medinenser (Anṣār) bereits nach dem Prinzip, ihre Angelegenheiten gemeinsam zu beraten; manche Mufassirūn beziehen 42:38 daher auch auf sie. Der Prophet ﷺ selbst beriet sich mit seinen Gefährten, etwa vor Badr und vor Uḥud.",
"42:23 sorgte für eine berühmte Deutungsfrage: „Sag: Ich verlange von euch keinen Lohn dafür, außer die Liebe in der Verwandtschaft (al-mawadda fī l-qurbā).“ Ibn ʿAbbās erklärte: Der Prophet ﷺ war mit jedem Clan der Quraisch verwandt – er bat sie: Wenn ihr mir nicht folgt, dann achtet wenigstens die Verwandtschaft zwischen uns und schadet mir nicht (Sahih al-Buchari, Nr. 4818)."],
asbab: ["Für die Sure ist kein Einzelanlass sahih überliefert. Zur Deutung von 42:23 korrigierte Ibn ʿAbbās den Saʿīd ibn Dschubair, der ‚die Verwandten Muhammads‘ verstanden hatte: Gemeint sei die Verwandtschaft des Propheten ﷺ mit den Quraisch selbst (Sahih al-Buchari, Nr. 4818)."],
begriffe: [
 {arab: "شُورَىٰ", tr: "schūrā", wurzel: "sch-w-r", erkl: "„Beratung“ (42:38) – ursprünglich das Gewinnen von Honig aus der Wabe: Man holt aus jedem das Beste heraus. Grundprinzip für Familie, Moschee, Gemeinde und Staat."},
 {arab: "لَيْسَ كَمِثْلِهِ شَيْء", tr: "laisa ka-mithlihī schaiʾ", wurzel: "m-th-l", erkl: "„Nichts ist Ihm gleich“ (42:11) – die Grundregel der Lehre über Allahs Eigenschaften: Man bestätigt, was Er über sich sagt (Hören, Sehen), ohne es mit Geschöpfen zu vergleichen."},
 {arab: "أَقِيمُوا الدِّين", tr: "aqīmū d-dīn", wurzel: "q-w-m", erkl: "„Haltet die Religion aufrecht und spaltet euch nicht darin“ (42:13) – der gemeinsame Auftrag aller großen Propheten. Die Spaltung kam „erst, nachdem das Wissen zu ihnen gekommen war – aus gegenseitigem Neid“ (42:14)."},
 {arab: "الْمَوَدَّة فِي الْقُرْبَىٰ", tr: "al-mawadda fī l-qurbā", wurzel: "w-d-d / q-r-b", erkl: "„Die Liebe in der Verwandtschaft“ (42:23) – nach Ibn ʿAbbās die Bitte des Propheten ﷺ an die Quraisch, die Verwandtschaft zu achten. Dieselbe Wurzel wie al-Wadūd (Lektion 27)."},
 {arab: "كَبَائِر الْإِثْم", tr: "kabāʾir al-ithm", wurzel: "k-b-r", erkl: "„Die großen Sünden“ (42:37) – die Gläubigen meiden sie und die Schändlichkeiten, „und wenn sie zornig sind, vergeben sie“. Zorn ist erlaubt, Rache nicht der erste Reflex."},
 {arab: "وَحْيًا أَوْ مِن وَرَاءِ حِجَابٍ", tr: "waḥyan au min warāʾi ḥidschāb", wurzel: "w-ḥ-y", erkl: "42:51 nennt die drei Wege, wie Allah zu Menschen spricht: durch Eingebung, hinter einem Vorhang (wie zu Mūsā) oder durch einen Gesandten-Engel (wie Dschibrīl). Der Grundvers über die Formen der Offenbarung."}
],
tafsir: [
 {vers: "Verse 1–12: Allah, über dem nichts ist", text: "„Fast brechen die Himmel von oben her auseinander“ (42:5) – aus Ehrfurcht vor Allahs Größe –, „und die Engel preisen ihren Herrn und bitten um Vergebung für die, die auf der Erde sind“. Dann 42:10: „Worüber ihr auch uneins seid – das Urteil darüber steht Allah zu.“ Und 42:11: der Satz, der in jedem ʿAqīda-Buch steht. Ibn Kathīr: Der Vers verneint jede Ähnlichkeit (laisa ka-mithlihī) und bestätigt zugleich die Eigenschaften (as-Samīʿ al-Baṣīr). Wer nur das Erste nimmt, leugnet; wer nur das Zweite nimmt, vermenschlicht. Die Sunna-Position hält beides."},
 {vers: "Verse 13–26: die eine Religion aller Propheten", text: "„Er hat euch an Religion verordnet, was Er Nūḥ anbefahl, was Wir dir offenbart haben und was Wir Ibrāhīm, Mūsā und ʿĪsā anbefohlen haben: Haltet die Religion aufrecht und spaltet euch nicht darin“ (42:13). As-Saʿdī: Fünf große Propheten, eine Botschaft – die Unterschiede liegen in einzelnen Gesetzen, nicht im Glauben. Spaltung entsteht aus „gegenseitigem Neid“ (baġyan bainahum), nicht aus Unwissenheit (42:14). Dann 42:20: „Wer die Ernte des Jenseits will, dem vermehren Wir seine Ernte; wer die Ernte des Diesseits will, dem geben Wir davon – doch im Jenseits hat er keinen Anteil.“ Und 42:23 mit der Bitte um Achtung der Verwandtschaft."},
 {vers: "Verse 27–35: Versorgung und Prüfung", text: "„Würde Allah Seinen Dienern die Versorgung reichlich bemessen, würden sie auf der Erde Gewalt üben; Er sendet sie nach Maß herab, wie Er will“ (42:27). Al-Qurṭubī: Nicht jeder verträgt Reichtum – Allahs Maß ist manchmal ein Schutz. Dann 42:30: „Was euch an Unglück trifft, ist wegen dessen, was eure Hände erworben haben – und Er verzeiht vieles.“ Die Gelehrten verbinden das mit dem Hadith: Kein Kummer, keine Krankheit, nicht einmal ein Dorn trifft den Muslim, ohne dass Allah damit Sünden tilgt (Sahih al-Buchari, Nr. 5641; Sahih Muslim, Nr. 2573). Unglück ist für den Gläubigen Reinigung."},
 {vers: "Verse 36–43: das Profil der Gemeinschaft", text: "Was bei Allah ist, ist besser für (1) die, die glauben und (2) auf ihren Herrn vertrauen, (3) die großen Sünden und Schändlichkeiten meiden, (4) im Zorn vergeben, (5) auf ihren Herrn hören und das Gebet verrichten, (6) ihre Angelegenheiten durch Beratung regeln, (7) von ihrer Versorgung ausgeben, (8) sich wehren, wenn ihnen Unrecht geschieht (42:36–39). Dann das Gleichgewicht: „Die Vergeltung für eine schlechte Tat ist eine gleich schlechte; wer aber vergibt und Frieden stiftet, dessen Lohn obliegt Allah“ (42:40). Und 42:43: „Wer geduldig ist und vergibt, das gehört zur Entschlossenheit.“ Ibn Kathīr: Der Islam erlaubt Gegenwehr gegen Unrecht – er ist keine Religion der Schwäche –, lobt aber die Vergebung als höhere Stufe. Beides hat seinen Ort: Vergebung, wenn sie den Täter bessert; Gegenwehr, wenn Nachgeben das Unrecht nur verstärkt."},
 {vers: "Verse 44–53: Rufe zu deinem Herrn", text: "Die Ungerechten am Tag des Gerichts, „demütig vor Schmach, mit verstohlenen Blicken“. Dann der Aufruf: „Folgt eurem Herrn, bevor ein Tag kommt, der nicht abgewendet werden kann“ (42:47). Allah schenkt, wem Er will, Töchter, wem Er will, Söhne, oder beides, oder macht unfruchtbar (42:49–50) – auffällig: Die Töchter werden zuerst genannt. Dann 42:51 über die Formen der Offenbarung und 42:52: „So haben Wir dir einen Geist (rūḥ) von Unserem Befehl offenbart … Wir haben ihn zu einem Licht gemacht.“ Der Koran ist Seele und Licht."}
],
ahadith: [
 {text: "Ibn ʿAbbās zu 42:23: Es gab keinen Clan der Quraisch, mit dem der Prophet ﷺ nicht verwandt war; er bat sie, die Verwandtschaft zu achten.", quelle: "Sahih al-Buchari, Nr. 4818"},
 {text: "„Keine Mühe, keine Krankheit, kein Kummer, keine Sorge, kein Leid und keine Betrübnis trifft den Muslim – nicht einmal ein Dorn, der ihn sticht –, ohne dass Allah damit etwas von seinen Sünden tilgt.“", quelle: "Sahih al-Buchari, Nr. 5641; Sahih Muslim, Nr. 2573"},
 {text: "„Allah hat keinem Diener wegen einer Vergebung etwas anderes vermehrt als Ehre.“ – zu 42:40.", quelle: "Sahih Muslim, Nr. 2588"},
 {text: "„Wer um Rat gefragt wird, ist ein Vertrauensträger (al-mustaschār muʾtaman).“", quelle: "Sunan Abū Dāwūd, Nr. 5128; at-Tirmidhī, Nr. 2822; sahih"}
],
hanafi: null,
umsetzung: [
 "Führe Schūrā in deiner Familie oder Gruppe ein: Eine wichtige Entscheidung diese Woche gemeinsam beraten – alle anhören, dann entscheiden.",
 "Wenn dich jemand um Rat fragt: Antworte ehrlich und vertraulich – nach Abū Dāwūd 5128 bist du dann ein Vertrauensträger.",
 "Lerne 42:11 als Grundregel für alle Fragen über Allah: nichts vergleichen, nichts leugnen.",
 "Prüfe deinen Zorn mit 42:37: Vergibst du, wenn du wütend bist, oder speicherst du ab? Übe einmal bewusst die Vergebung im Moment des Zorns.",
 "Lies 42:30 bei jedem Unglück zusammen mit Buchari 5641: Es ist auch Reinigung – sprich Istiġfār und Geduld statt Klage."
]
},

// ───────────────────────── Lektion 63: Az-Zuchruf ─────────────────────────
{
sure: 43, offb: 63, name: "Az-Zuchruf", arab: "سُورَةُ الزُّخْرُفِ", de: "Der Prunk", verse: 89, ort: "Mekka",
zeit: "Spätmekkanisch – gegen die Überzeugung der Quraisch, Reichtum sei ein Zeichen göttlicher Gunst",
kurz: "Die Sure gegen das Denken in Gold und Status. Die Quraisch sagten: „Warum wurde dieser Koran nicht einem bedeutenden Mann aus den beiden Städten (Mekka und Ṭāʾif) herabgesandt?“ Die Antwort ist vernichtend: Wäre es nicht, dass alle Menschen dann den Unglauben wählen würden, hätte Allah den Ungläubigen Dächer aus Silber, Treppen, Türen und Liegen gegeben – und Prunk. „All das ist nur Genuss des diesseitigen Lebens; das Jenseits aber ist bei deinem Herrn für die Gottesfürchtigen.“ Die Sure zeigt Pharao als Prototyp dessen, der mit Besitz argumentiert („Gehört mir nicht das Königreich Ägypten und diese Flüsse?“) und Mūsā verachtet. Sie lehrt das Reisegebet, entlarvt das blinde Festhalten an den Vätern und warnt: „Die engen Freunde werden an jenem Tag einander Feinde sein – außer den Gottesfürchtigen.“",
schluessel: {arab: "الْأَخِلَّاءُ يَوْمَئِذٍ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا الْمُتَّقِينَ", ueb: "Die engen Freunde werden an jenem Tag einander Feinde sein – außer den Gottesfürchtigen.", ref: "43:67"},
kontext: ["Die Mekkaner dachten in Rangordnungen. Als die Offenbarung zu einem Waisenkind ohne großes Vermögen kam, empörten sie sich: Warum nicht zu al-Walīd ibn al-Muġīra in Mekka oder ʿUrwa ibn Masʿūd ath-Thaqafī in Ṭāʾif? (so die Tafsir-Berichte zu 43:31). Die Sure antwortet: „Verteilen etwa sie die Barmherzigkeit deines Herrn?“ (43:32) – Allah verteilt die Versorgung im Diesseits, und noch viel mehr verteilt Er die Prophetenschaft.",
"Ein zweites Thema ist das Argument der Tradition: „Wir fanden unsere Väter auf einem Weg, und wir folgen ihren Spuren“ (43:22–23). Die Sure stellt dem Ibrāhīm gegenüber, der sich von seinem Vater und seinem Volk lossagte – „außer von Dem, Der mich erschaffen hat“ (43:26–27). Tradition ist nicht automatisch Wahrheit.",
"43:57–58 spielt auf eine Debatte an: Als 21:98 herabkam („Ihr und das, was ihr neben Allah anbetet, seid Brennstoff der Hölle“), sagte ʿAbdullāh ibn az-Zibaʿrā: „Dann sind ja auch ʿĪsā und die Engel in der Hölle, denn sie werden angebetet!“ Die Quraisch lachten. Der Koran antwortet: Sie stellen das nur als Streitfrage hin – ʿĪsā war ein Diener, dem Allah Gunst erwies (Tafsir-Bericht bei aṭ-Ṭabarī und Ibn Kathīr)."],
asbab: [
 {text: "43:31: Die Quraisch fragten, warum der Koran nicht einem großen Mann der beiden Städte (Mekka und Ṭāʾif) herabgesandt wurde – genannt werden al-Walīd ibn al-Muġīra und ʿUrwa ibn Masʿūd.", quelle: "Tafsir aṭ-Ṭabarī und Ibn Kathīr zu 43:31"},
 {text: "43:57–58: die Streitfrage des Ibn az-Zibaʿrā über ʿĪsā. Dazu der Hadith: „Kein Volk ging nach einer Rechtleitung, auf der es war, in die Irre, ohne dass ihm Streitsucht gegeben wurde“ – dann rezitierte der Prophet ﷺ 43:58.", quelle: "Tafsir-Bericht; Hadith: Sunan at-Tirmidhī, Nr. 3253; hasan"}
],
begriffe: [
 {arab: "الزُّخْرُف", tr: "az-zuchruf", wurzel: "z-ch-r-f", erkl: "Prunk, Goldschmuck, Verzierung (43:35). Allah würde den Ungläubigen Prunk geben, wenn das die Menschen nicht in den Unglauben treiben würde – so wenig ist er wert."},
 {arab: "مُقْتَدُون", tr: "muqtadūn", wurzel: "q-d-w", erkl: "„Wir folgen (ihren Spuren)“ (43:23) – das Argument der Väter. Taqlīd im Glauben ohne Prüfung ist im Koran ein Zeichen der Verstocktheit; Ibrāhīm brach es."},
 {arab: "سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَٰذَا", tr: "subḥāna lladhī sachchara lanā hādhā", wurzel: "s-ch-r", erkl: "„Gepriesen sei Der, Der uns dies dienstbar gemacht hat – wir hätten es nicht vermocht – und zu unserem Herrn kehren wir zurück“ (43:13–14). Das Reisegebet, das der Prophet ﷺ beim Aufsteigen auf das Reittier sprach (Sahih Muslim, Nr. 1342)."},
 {arab: "يَعْشُ عَن ذِكْرِ الرَّحْمَٰن", tr: "yaʿschu ʿan dhikri r-Raḥmān", wurzel: "ʿ-sch-w", erkl: "„Wer sich blind stellt gegenüber dem Gedenken des Allerbarmers, dem teilen Wir einen Satan zu, der ihm zum Begleiter wird“ (43:36). Wer den Dhikr verlässt, bekommt einen anderen Begleiter."},
 {arab: "الْأَخِلَّاء", tr: "al-achillāʾ", wurzel: "ch-l-l", erkl: "„Die engen Freunde“ (43:67) – von chalīl, dem innigsten Freund. Freundschaften, die nicht auf Taqwā gebaut sind, werden am Jüngsten Tag zu Feindschaften."},
 {arab: "قِيلِهِ يَا رَبِّ", tr: "qīlihī yā rabbi", wurzel: "q-w-l", erkl: "43:88: „Und (Er kennt) sein Wort: O mein Herr, das sind Leute, die nicht glauben.“ Die Klage des Propheten ﷺ – und die Antwort 43:89: „So übe Nachsicht mit ihnen und sag: Frieden!“"}
],
tafsir: [
 {vers: "Verse 1–25: das klare Buch und die Ausreden", text: "Der Koran ist „im Urbuch bei Uns erhaben und voller Weisheit“ (43:4). Die Schöpfung als Zeichen: die Erde als Wiege, Wege darin, Regen nach Maß, die Paare, Schiffe und Reittiere – und das Reisegebet (43:12–14). Dann die Ausreden der Götzendiener: Sie machen Allah Töchter, obwohl sie sich selbst über die Geburt einer Tochter grämen (43:16–17, vgl. Lektion 23), und sie sagen: „Hätte der Allerbarmer es gewollt, hätten wir sie nicht angebetet“ (43:20) – das Schicksals-Argument als Ausrede. Al-Qurṭubī: Wer sich auf Allahs Willen beruft, um eigene Sünden zu rechtfertigen, verwechselt Allahs Schöpfungswillen mit Seinem Gesetzeswillen."},
 {vers: "Verse 26–45: Ibrāhīm, Prunk und der Begleiter", text: "Ibrāhīm sagt sich los: „Ich bin unschuldig an dem, was ihr anbetet, außer an Dem, Der mich erschaffen hat“ (43:26–27), und macht das Bekenntnis zu einem „bleibenden Wort in seiner Nachkommenschaft“. Dann der Status-Einwand (43:31) und die Antwort: Allah hat die Versorgung verteilt und manche über andere gestellt, „damit die einen die anderen in Dienst nehmen“ – gegenseitige Abhängigkeit ist Teil der Ordnung, kein Rangbeweis vor Allah (43:32). Dann 43:33–35: Silber und Prunk für die Ungläubigen, wenn es nicht alle verführen würde. Der Prophet ﷺ sagte: „Wäre die Welt bei Allah so viel wert wie ein Mückenflügel, hätte Er einem Ungläubigen daraus keinen Schluck Wasser gegeben“ (at-Tirmidhī, Nr. 2320; sahih). Dann 43:36–39 über den Satan-Begleiter: Am Jüngsten Tag sagt der Mensch: „O wäre doch zwischen mir und dir die Entfernung der beiden Osten!“"},
 {vers: "Verse 46–56: Pharao und das Argument des Besitzes", text: "Pharao ruft sein Volk: „Gehört mir nicht das Königreich Ägypten und diese Flüsse, die unter mir fließen? … Bin ich nicht besser als dieser da, der verächtlich ist und sich kaum verständlich ausdrücken kann? Warum wurden ihm keine Goldarmreifen umgelegt?“ (43:51–53). Und dann der entscheidende Vers 43:54: „So verleitete er sein Volk zum Leichtsinn (fa-staḫaffa qaumahu), und sie gehorchten ihm.“ Ibn Kathīr: Der Tyrann macht sein Volk ‚leicht', geistig oberflächlich – dann folgt es ihm. Machtpropaganda funktioniert, wo Menschen nicht nachdenken."},
 {vers: "Verse 57–89: ʿĪsā, die Freunde und das Paradies", text: "Die Ibn-az-Zibaʿrā-Debatte (43:57–58) und die Klarstellung über ʿĪsā: „Er ist nur ein Diener, dem Wir Gunst erwiesen und den Wir zum Beispiel für die Kinder Isrāʾīl gemacht haben“ (43:59). 43:61: „Er (ʿĪsā) ist ein Wissen (Zeichen) für die Stunde“ – nach der Mehrheit ein Hinweis auf seine Wiederkunft vor dem Jüngsten Tag. Dann die Freundes-Warnung 43:67 und das Paradies: „O Meine Diener, keine Furcht ist heute über euch … Tretet ins Paradies ein, ihr und eure Gattinnen, voller Freude“ – mit goldenen Schüsseln und Bechern, „und darin ist, was die Seelen begehren und woran die Augen sich erfreuen“ (43:70–71). Das Gold, das im Diesseits nichts wert war, gehört im Jenseits den Gottesfürchtigen. Schluss: „Gesegnet ist Der, Dem die Herrschaft der Himmel und der Erde gehört“ und die Anweisung an den Propheten ﷺ: „Übe Nachsicht mit ihnen und sag: Frieden!“"}
],
ahadith: [
 {text: "Das Reisegebet des Propheten ﷺ beim Aufsteigen auf das Reittier: Allāhu akbar (3×), dann „subḥāna lladhī sachchara lanā hādhā wa-mā kunnā lahu muqrinīn, wa-innā ilā rabbinā la-munqalibūn …“", quelle: "Sahih Muslim, Nr. 1342"},
 {text: "„Wäre die Welt bei Allah so viel wert wie ein Mückenflügel, hätte Er einem Ungläubigen daraus keinen Schluck Wasser zu trinken gegeben.“", quelle: "Sunan at-Tirmidhī, Nr. 2320; sahih"},
 {text: "„Kein Volk ging nach einer Rechtleitung, auf der es war, in die Irre, ohne dass ihm Streitsucht gegeben wurde“ – dann rezitierte er 43:58.", quelle: "Sunan at-Tirmidhī, Nr. 3253; hasan"},
 {text: "„Der Mensch folgt der Religion seines engen Freundes – so schaue jeder von euch, wen er zum engen Freund nimmt.“ – zu 43:67.", quelle: "Sunan Abū Dāwūd, Nr. 4833; at-Tirmidhī, Nr. 2378; hasan"}
],
hanafi: "Zu 43:18 (das Mädchen, „das im Schmuck aufgezogen wird“) und den goldenen Gefäßen des Paradieses (43:71) passt eine hanafitische Rechtsregel: Gold und reine Seide sind für Männer verboten, für Frauen erlaubt; das Essen und Trinken aus Gold- und Silbergefäßen ist für Männer und Frauen verboten („Trinkt nicht aus Gold- und Silbergefäßen … sie sind für sie im Diesseits und für euch im Jenseits“ – Sahih al-Buchari, Nr. 5426; Sahih Muslim, Nr. 2067). Der Mann darf nach der hanafitischen Schule einen silbernen Ring tragen, keinen goldenen.",
umsetzung: [
 "Lerne das Reisegebet (Muslim 1342) und sprich es beim Einsteigen ins Auto, in den Zug oder ins Flugzeug – 43:13–14 wird dann jeden Tag lebendig.",
 "Mach den 43:54-Test bei dir: Welche Medien, Werbung oder Persönlichkeiten machen dich ‚leicht' – oberflächlich, schnell beeinflussbar? Reduziere sie bewusst.",
 "Prüfe ererbte Gewohnheiten (43:22): Welche religiöse oder kulturelle Praxis machst du nur, ‚weil man das bei uns so macht'? Prüfe sie an Koran und Sunna.",
 "Investiere in Freundschaften, die auch am Jüngsten Tag halten (43:67): Lade einen Freund zu Gebet, Lernen oder Spende ein – gemeinsame Taqwā ist die einzige Freundschaft mit Garantie."
]
},

// ───────────────────────── Lektion 64: Ad-Duchān ─────────────────────────
{
sure: 44, offb: 64, name: "Ad-Duchān", arab: "سُورَةُ الدُّخَانِ", de: "Der Rauch", verse: 59, ort: "Mekka",
zeit: "Spätmekkanisch – während einer schweren Hungersnot, die die Quraisch traf",
kurz: "Die Quraisch lehnten den Propheten ﷺ hartnäckig ab, und er bat Allah, sie mit Jahren wie den sieben Jahren Yūsufs zu prüfen. Eine Hungersnot kam: Die Menschen aßen Knochen und Verendetes, und wenn einer zum Himmel schaute, sah er vor Hunger etwas wie Rauch. Darüber spricht diese Sure: „So erwarte den Tag, an dem der Himmel einen deutlichen Rauch bringt.“ Abū Sufyān kam und bat den Propheten ﷺ um Regen für sein Volk – und er betete für sie. Die Sure beginnt mit der „gesegneten Nacht“, in der der Koran herabkam (vgl. Lektion 25), erzählt vom Untergang Pharaos, der Gärten und Quellen hinterließ, über die „weder Himmel noch Erde weinten“, und stellt den Zaqqūm-Baum der Sünder den Gärten der Gottesfürchtigen gegenüber.",
schluessel: {arab: "إِنَّا أَنزَلْنَاهُ فِي لَيْلَةٍ مُّبَارَكَةٍ ۚ إِنَّا كُنَّا مُنذِرِينَ", ueb: "Wir haben ihn (den Koran) in einer gesegneten Nacht herabgesandt – Wir sind es ja, die warnen.", ref: "44:3"},
kontext: ["Ibn Masʿūd berichtet: Als die Quraisch sich dem Propheten ﷺ widersetzten, betete er gegen sie um Jahre wie die Jahre Yūsufs. Eine Dürre traf sie, bis sie Knochen aßen; ein Mann schaute zum Himmel und sah zwischen sich und dem Himmel etwas wie Rauch vor lauter Erschöpfung. Da kam 44:10–11 herab. Dann kam (Abū Sufyān) zum Propheten ﷺ und sagte: „Bitte Allah um Regen für (den Stamm) Muḍar, sie gehen zugrunde.“ Er betete, und es regnete. Daraufhin kam 44:15 herab: „Wir nehmen die Strafe ein wenig weg – doch ihr kehrt zurück“ (Sahih al-Buchari, Nr. 4821; Sahih Muslim, Nr. 2798). Ibn Masʿūd deutete auch den „großen Zugriff“ (44:16) als den Tag von Badr.",
"Andere Gelehrte (u. a. nach einer Überlieferung von Ibn ʿAbbās) verstehen den Rauch als eines der großen Zeichen vor dem Jüngsten Tag – auch der Hadith der zehn Zeichen nennt den Rauch (Sahih Muslim, Nr. 2901). Ibn Kathīr hält beide Deutungen für möglich: ein Rauch, der Mekka traf, und ein Rauch, der noch kommt.",
"Die Sure ist die fünfte der Ḥā-Mīm-Suren. Ihre Verbindung zu Al-Qadr (Lektion 25) ist eng: Die gesegnete Nacht ist nach der Mehrheit die Lailat al-Qadr, „in der jede weise Angelegenheit entschieden wird“ (44:4)."],
asbab: [
 {text: "44:10–16: die Hungersnot der Quraisch nach dem Gebet des Propheten ﷺ, der ‚Rauch' vor Hunger, die Bitte Abū Sufyāns um Regen und die Wiederkehr der Quraisch zum Unglauben.", quelle: "Sahih al-Buchari, Nr. 4821; Sahih Muslim, Nr. 2798"}
],
begriffe: [
 {arab: "لَيْلَة مُّبَارَكَة", tr: "laila mubāraka", wurzel: "b-r-k", erkl: "„Eine gesegnete Nacht“ (44:3) – nach der Mehrheit die Lailat al-Qadr im Ramadan (vgl. 97:1 und 2:185). Baraka: Wachstum und Fülle des Guten, das bleibt."},
 {arab: "يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ", tr: "yufraqu kullu amrin ḥakīm", wurzel: "f-r-q", erkl: "„In ihr wird jede weise Angelegenheit entschieden“ (44:4) – die Jahresbestimmungen werden in dieser Nacht festgeschrieben (vgl. Lektion 25)."},
 {arab: "الدُّخَان", tr: "ad-duchān", wurzel: "d-ch-n", erkl: "„Der Rauch“ (44:10) – nach Ibn Masʿūd der Hungerrauch über Mekka, nach anderen ein Zeichen vor der Stunde. Beides zeigt: Allah warnt erst, bevor Er straft."},
 {arab: "الْبَطْشَة الْكُبْرَىٰ", tr: "al-baṭscha al-kubrā", wurzel: "b-ṭ-sch", erkl: "„Der große Zugriff“ (44:16) – nach Ibn Masʿūd der Tag von Badr, nach anderen der Jüngste Tag."},
 {arab: "فَمَا بَكَتْ عَلَيْهِمُ السَّمَاءُ وَالْأَرْضُ", tr: "fa-mā bakat ʿalaihimu s-samāʾu wa-l-arḍ", wurzel: "b-k-y", erkl: "„Weder Himmel noch Erde weinten über sie“ (44:29) – über Pharao und seine Leute. Die Gelehrten sagen: Über den Gläubigen weinen der Ort seines Gebets auf der Erde und das Tor im Himmel, durch das seine Taten aufstiegen."},
 {arab: "مَقَام أَمِين", tr: "maqām amīn", wurzel: "ʾ-m-n", erkl: "„Ein sicherer Aufenthaltsort“ (44:51) für die Gottesfürchtigen – in Gärten und Quellen, gekleidet in Seide, ohne den Tod zu kosten außer dem ersten (44:56)."}
],
tafsir: [
 {vers: "Verse 1–16: gesegnete Nacht und Rauch", text: "Schwur beim klaren Buch, dann die Herabsendung in der gesegneten Nacht (44:3–6) „als Barmherzigkeit von deinem Herrn“. Dann ein harter Satz: „Doch sie sind im Zweifel und treiben ihr Spiel“ (44:9) – sie nehmen die Botschaft nicht ernst. Darauf der Rauch (44:10–11) und ihr Ruf: „Unser Herr, nimm die Strafe von uns weg, wir sind gläubig!“ (44:12). Aber: „Wie soll ihnen die Ermahnung nützen, wo doch ein klarer Gesandter zu ihnen gekommen war und sie sich abwandten und sagten: ein Belehrter, ein Besessener!“ (44:13–14). As-Saʿdī: Notgebete sind ehrlich in der Not und vergessen in der Erleichterung – so war Mekka, und so sind viele Menschen (vgl. 41:51 in Lektion 61)."},
 {vers: "Verse 17–33: Pharao und Mūsā", text: "Allah prüfte vor ihnen das Volk Pharaos: Mūsā kam als „ehrenvoller Gesandter“ und sagte: „Übergebt mir die Diener Allahs“ (44:18) – die Befreiung der Kinder Isrāʾīl. Als sie ihn bedrohten, suchte er Zuflucht bei Allah, und Allah befahl: „Zieh nachts mit Meinen Dienern fort … und lass das Meer ruhig (offen) zurück“ (44:23–24). Dann der Untergang: „Wie viele Gärten und Quellen ließen sie zurück, Felder und edle Wohnstätten, und Wohlleben, in dem sie es sich gut gehen ließen!“ (44:25–27) – „und Wir gaben es einem anderen Volk zum Erbe“. Ibn Kathīr zu 44:29: Weder Himmel noch Erde weinten über sie, denn sie hatten auf der Erde keine guten Taten hinterlassen und keine zum Himmel aufsteigen lassen."},
 {vers: "Verse 34–42: die Leugner der Auferstehung", text: "Die Quraisch sagen: „Es gibt nur unseren ersten Tod, wir werden nicht auferweckt. Bringt doch unsere Väter zurück, wenn ihr wahrhaftig seid“ (44:34–36). Antwort: Waren sie besser als das Volk von Tubbaʿ (die Könige des Jemen), die vernichtet wurden? Und: „Wir haben die Himmel und die Erde nicht zum Spiel erschaffen – Wir haben sie nur mit der Wahrheit erschaffen“ (44:38–39). Der ‚Tag der Entscheidung' (yaum al-faṣl, vgl. Lektion 33) ist der festgesetzte Termin für alle."},
 {vers: "Verse 43–59: Zaqqūm und das Paradies", text: "„Der Baum Zaqqūm ist die Speise des Sünders – wie geschmolzenes Metall kocht er in den Bäuchen“ (44:43–46, vgl. Lektion 56). Dann die Spottworte an den Hochmütigen: „Koste! Du bist ja der Mächtige, der Edle!“ (44:49) – die Tafsir-Berichte beziehen es auf Abū Dschahl, der sich so nannte. Gegenbild: die Gottesfürchtigen an einem sicheren Ort, in Gärten und Quellen, in Seide, einander gegenüber, mit Gefährtinnen mit großen Augen; „sie kosten darin den Tod nicht, außer dem ersten Tod“ (44:56). Al-Qurṭubī: Es gibt nach dem Tod keinen Tod mehr – das Paradies ist ewig. Schluss: „Wir haben ihn (den Koran) in deiner Sprache leicht gemacht, auf dass sie bedenken“ (44:58, vgl. 54:17 in Lektion 37) – „so warte ab, auch sie warten ab“."}
],
ahadith: [
 {text: "Ibn Masʿūd: Die Hungersnot der Quraisch, der ‚Rauch' vor Erschöpfung, die Bitte um Regen für Muḍar – und die Herabsendung von 44:10–16.", quelle: "Sahih al-Buchari, Nr. 4821; Sahih Muslim, Nr. 2798"},
 {text: "Die zehn großen Zeichen vor der Stunde – darunter der Rauch, der Daddschāl, das Tier, der Aufgang der Sonne im Westen, der Abstieg ʿĪsās …", quelle: "Sahih Muslim, Nr. 2901 (Ḥudhaifa ibn Asīd)"},
 {text: "„Der Tod wird (am Jüngsten Tag) in Gestalt eines Widders gebracht und zwischen Paradies und Hölle geschlachtet – dann wird gesagt: O Leute des Paradieses, Ewigkeit ohne Tod!“ – zu 44:56.", quelle: "Sahih al-Buchari, Nr. 4730; Sahih Muslim, Nr. 2849"}
],
hanafi: null,
umsetzung: [
 "Prüfe dein Notgebet-Muster (44:12–15): Woran hast du in einer Krise Allah versprochen, dich zu bessern – und hast du es gehalten? Erfülle diese Woche ein vergessenes Versprechen.",
 "Hinterlasse Spuren, über die Himmel und Erde weinen (44:29): ein fester Gebetsplatz zu Hause, regelmäßige gute Taten, die zum Himmel aufsteigen.",
 "Nimm die Sure als Vorbereitung auf den Ramadan: Sie verbindet die gesegnete Nacht mit dem Koran – plane für die letzten zehn Nächte Koran-Lesezeiten.",
 "Sei wie der Prophet ﷺ bei Abū Sufyān: Selbst für die, die dich ablehnen, bete um Gutes, wenn sie in Not sind."
]
},

// ───────────────────────── Lektion 65: Al-Dschāthiya ─────────────────────────
{
sure: 45, offb: 65, name: "Al-Dschāthiya", arab: "سُورَةُ الْجَاثِيَةِ", de: "Die Kniende", verse: 37, ort: "Mekka",
zeit: "Spätmekkanisch – gegen die Haltung, die nur die Zeit (dahr) als Ursache von Leben und Tod anerkennt",
kurz: "Die Sure richtet sich gegen eine Haltung, die heute weit verbreitet ist: „Es gibt nur unser diesseitiges Leben; wir sterben und leben, und nur die Zeit (ad-dahr) vernichtet uns.“ Das ist die alte Form des Materialismus – und der Koran antwortet: „Sie haben darüber kein Wissen, sie vermuten nur.“ Ihr bekanntester Vers trifft das Herz jeder Ideologie: „Hast du den gesehen, der seine Neigung zu seinem Gott nimmt?“ Die Sure beginnt mit den Zeichen in Himmel, Erde, Tieren und Winden und endet mit einer der eindrucksvollsten Gerichtsszenen: „Und du siehst jede Gemeinschaft kniend; jede Gemeinschaft wird zu ihrem Buch gerufen.“",
schluessel: {arab: "أَفَرَأَيْتَ مَنِ اتَّخَذَ إِلَٰهَهُ هَوَاهُ وَأَضَلَّهُ اللَّهُ عَلَىٰ عِلْمٍ", ueb: "Hast du den gesehen, der seine Neigung zu seinem Gott nimmt und den Allah trotz (seines) Wissens irregehen lässt?", ref: "45:23"},
kontext: ["Unter den Arabern gab es neben Götzendienern auch eine Gruppe, die man später ‚Dahriyya' nannte: Menschen, die keinen Schöpfer und kein Jenseits annahmen und alles der Zeit zuschrieben. 45:24 zitiert sie: „Es gibt nur unser diesseitiges Leben … und nur die Zeit vernichtet uns.“ Diese Haltung ist modern geblieben: ‚Das Universum ist einfach da', ‚Wir sind ein Zufall der Zeit'.",
"Der Prophet ﷺ überlieferte dazu einen Hadith Qudsi: „Der Sohn Ādams kränkt Mich: Er beschimpft die Zeit (ad-dahr) – dabei bin Ich die Zeit; in Meiner Hand ist die Angelegenheit, Ich wechsle Nacht und Tag“ (Sahih al-Buchari, Nr. 4826; Sahih Muslim, Nr. 2246). Die Gelehrten erklären: Wer die Zeit beschimpft (‚diese verdammten Zeiten'), beschimpft in Wahrheit Den, Der die Ereignisse lenkt.",
"Al-Dschāthiya ist die sechste der Ḥā-Mīm-Suren. Ihren Namen hat sie von 45:28: Die Gemeinschaften knien vor dem Gericht – ein Bild äußerster Demut und Erwartung."],
asbab: ["Für die Sure ist kein sahih gesicherter Einzelanlass überliefert. Zu 45:14 („Sag denen, die glauben, sie sollen denen vergeben, die nicht auf die Tage Allahs hoffen“) nennen manche Tafsir-Werke Vorfälle mit ʿUmar in Mekka; die Ketten sind schwach. Der Vers gilt allgemein."],
begriffe: [
 {arab: "الْجَاثِيَة", tr: "al-dschāthiya", wurzel: "dsch-th-w", erkl: "„Die Kniende“ (45:28) – jede Gemeinschaft kniet am Jüngsten Tag vor dem Gericht. Kein Volk, keine Partei, keine Nation steht dann aufrecht da."},
 {arab: "هَوَاهُ", tr: "hawāhu", wurzel: "h-w-y", erkl: "„Seine Neigung/Lust“ (45:23) – wer seine Neigungen zum Maßstab macht, hat sie zu seinem Gott gemacht. Dieselbe Wurzel wie hāwiya (Abgrund, Lektion 30)."},
 {arab: "عَلَىٰ عِلْمٍ", tr: "ʿalā ʿilm", wurzel: "ʿ-l-m", erkl: "„Trotz Wissens“ (45:23) – das Erschreckende: Er weiß es eigentlich besser. Wissen allein rettet nicht, wenn die Neigung herrscht."},
 {arab: "الدَّهْر", tr: "ad-dahr", wurzel: "d-h-r", erkl: "„Die Zeit, das Schicksal“ (45:24) – die ‚Ursache', auf die sich die Leugner berufen. Allah sagt im Hadith Qudsi: „Ich bin der Dahr“ – d. h. Ich lenke die Zeit."},
 {arab: "شَرِيعَة", tr: "scharīʿa", wurzel: "sch-r-ʿ", erkl: "„Ein (klarer) Weg“ (45:18): „Dann haben Wir dich auf einen Weg (scharīʿa) in der Angelegenheit gestellt – so folge ihm und folge nicht den Neigungen derer, die nicht wissen.“ Ursprünglich der Weg zur Wasserstelle: der Weg zum Leben."},
 {arab: "نَسْتَنسِخُ", tr: "nastansichu", wurzel: "n-s-ch", erkl: "„Wir ließen aufzeichnen“ (45:29): „Das ist Unser Buch, es spricht gegen euch mit der Wahrheit; Wir ließen aufzeichnen, was ihr zu tun pflegtet.“ Das vollständige Protokoll (vgl. Lektion 34)."}
],
tafsir: [
 {vers: "Verse 1–15: Zeichen und Geduld", text: "„In den Himmeln und auf der Erde sind wahrlich Zeichen für die Gläubigen; in eurer Erschaffung und in dem, was Er an Tieren verbreitet, sind Zeichen für Leute, die Gewissheit haben; im Wechsel von Nacht und Tag, im Regen und im Wechsel der Winde sind Zeichen für Leute, die verstehen“ (45:3–5). Die Stufen: glauben, Gewissheit haben, verstehen. Dann die Warnung vor jedem „Lügner und Sünder“, der die Verse hört und dann hochmütig verharrt, „als hätte er sie nicht gehört“ (45:7–8). 45:13: „Er hat euch dienstbar gemacht, was in den Himmeln und auf der Erde ist – alles von Ihm.“ Und 45:14: Die Gläubigen sollen denen vergeben, die nicht auf die Tage Allahs hoffen – Allah wird jedes Volk nach seinem Tun belohnen."},
 {vers: "Verse 16–23: die Scharīʿa und die Neigung", text: "Die Kinder Isrāʾīl erhielten Schrift, Urteil und Prophetentum, und sie wurden uneins „erst nachdem das Wissen zu ihnen gekommen war, aus gegenseitigem Neid“ (45:17, vgl. 42:14 in Lektion 62). Dann 45:18 an den Propheten ﷺ: Folge der Scharīʿa, nicht den Neigungen der Unwissenden. Dann 45:21: „Meinen diejenigen, die Böses begehen, Wir würden sie denen gleichstellen, die glauben und Gutes tun?“ Und 45:23: der Mensch, der seine Neigung zum Gott macht. Ibn Kathīr: Er tut, was ihm gefällt, und lässt, was ihm nicht gefällt – der Maßstab ist er selbst. Allah versiegelt sein Gehör und Herz und legt eine Hülle auf sein Augenlicht. As-Saʿdī: Das ist die Religion vieler Menschen heute, auch ohne Götzen – ‚Ich mache, was sich für mich richtig anfühlt'."},
 {vers: "Verse 24–27: die Zeit-Theorie", text: "„Sie sagen: Es gibt nur unser diesseitiges Leben; wir sterben und leben, und nur die Zeit vernichtet uns. Sie haben darüber kein Wissen, sie stellen nur Vermutungen an“ (45:24). Al-Qurṭubī: Der Koran stellt fest, dass auch der Atheismus ein Glaube ist – ein Glaube ohne Beweis. Ihr ‚Argument': „Bringt doch unsere Väter zurück!“ (45:25). Antwort: „Allah macht euch lebendig, dann lässt Er euch sterben, dann versammelt Er euch zum Tag der Auferstehung“ (45:26) – die Auferstehung ist kein Experiment auf Bestellung, sondern ein Termin."},
 {vers: "Verse 28–37: die knienden Gemeinschaften", text: "„Du siehst jede Gemeinschaft kniend; jede Gemeinschaft wird zu ihrem Buch gerufen. Heute wird euch vergolten, was ihr zu tun pflegtet“ (45:28). Das Buch spricht mit der Wahrheit (45:29). Die Gläubigen gehen in Allahs Barmherzigkeit ein; zu den Ungläubigen wird gesagt: „Heute vergessen Wir euch, wie ihr die Begegnung mit diesem eurem Tag vergessen habt“ (45:34) – Strafe in der Form der Tat. „Das ist so, weil ihr die Verse Allahs zum Spott genommen habt und das diesseitige Leben euch betört hat“ (45:35). Schluss: „Allah gehört das Lob, dem Herrn der Himmel, dem Herrn der Erde, dem Herrn der Welten. Ihm gehört die Größe (al-kibriyāʾ) in den Himmeln und auf der Erde“ (45:36–37). Die Größe gehört Ihm allein – darum ist Hochmut beim Menschen Anmaßung."}
],
ahadith: [
 {text: "Hadith Qudsi: „Der Sohn Ādams kränkt Mich: Er beschimpft die Zeit – dabei bin Ich die Zeit; in Meiner Hand ist die Angelegenheit, Ich wechsle Nacht und Tag.“", quelle: "Sahih al-Buchari, Nr. 4826; Sahih Muslim, Nr. 2246"},
 {text: "Hadith Qudsi: „Die Größe (al-kibriyāʾ) ist Mein Mantel und die Erhabenheit Mein Gewand – wer Mir eines davon streitig macht, den werfe Ich ins Feuer.“ – zu 45:37.", quelle: "Sunan Abū Dāwūd, Nr. 4090; sahih (vgl. Sahih Muslim, Nr. 2620)"},
 {text: "„Keiner von euch ist (wirklich) gläubig, bis seine Neigung dem folgt, womit ich gekommen bin.“ – zu 45:23. Die Kette ist umstritten; an-Nawawī nahm ihn in die 40 Hadithe auf.", quelle: "an-Nawawī, al-Arbaʿīn, Nr. 41 (Kette von Ibn Radschab als schwach eingestuft)"}
],
hanafi: null,
umsetzung: [
 "Hör auf, die Zeit zu beschimpfen (Buchari 4826): Statt ‚diese schlimmen Zeiten' sag ‚Allah lenkt die Zeiten' – und frag, was du in dieser Zeit tun kannst.",
 "Mach den 45:23-Test: Nenne eine Sache, bei der du weißt, was der Islam sagt, aber deiner Neigung folgst. Das ist dein ‚kleiner Götze' – arbeite an ihm.",
 "Lerne im Gespräch mit Atheisten die Ruhe von 45:24: Nicht beschimpfen, sondern fragen – „Welches Wissen hast du darüber?“ Der Koran nennt es Vermutung.",
 "Denk an das Knien (45:28), wenn du dich groß fühlst: Jede Gruppe, jede Nation, jeder Einzelne wird knien. Demut jetzt ist leichter als Demut dann."
]
},

// ───────────────────────── Lektion 66: Al-Aḥqāf ─────────────────────────
{
sure: 46, offb: 66, name: "Al-Aḥqāf", arab: "سُورَةُ الْأَحْقَافِ", de: "Die Sanddünen", verse: 35, ort: "Mekka",
zeit: "Spätmekkanisch – nach der Rückkehr aus Ṭāʾif, im Jahr der Trauer; die letzte der Ḥā-Mīm-Suren",
kurz: "Die letzte Ḥā-Mīm-Sure ist eine Sure des Trostes in schwerster Zeit. Sie erzählt von zwei Söhnen: dem dankbaren, der mit vierzig Jahren betet: „Mein Herr, gib mir ein, für Deine Gabe dankbar zu sein, die Du mir und meinen Eltern erwiesen hast“ – und dem undankbaren, der seine Eltern anfährt: „Pfui über euch beide! Wollt ihr mir androhen, dass ich auferweckt werde?“ Sie erzählt vom Volk ʿĀd in den Sanddünen, das eine Wolke sah und jubelte: „Das ist eine Wolke, die uns Regen bringt!“ – doch es war ein vernichtender Wind. Und sie erzählt von der Schar der Dschinn, die den Koran hörte und als Warner zu ihrem Volk zurückkehrte (vgl. Lektion 40). Der Schluss ist der Rat an den Propheten ﷺ: „So sei geduldig, wie die Gesandten mit Entschlossenheit (ulū l-ʿazm) geduldig waren.“",
schluessel: {arab: "رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ", ueb: "Mein Herr, gib mir ein, für Deine Gabe dankbar zu sein, die Du mir und meinen Eltern erwiesen hast, und Rechtschaffenes zu tun, mit dem Du zufrieden bist.", ref: "46:15"},
kontext: ["Al-Aḥqāf fällt nach vielen Gelehrten in die Zeit nach der Rückkehr aus Ṭāʾif – das ‚Jahr der Trauer', in dem Chadīdscha und Abū Ṭālib starben und Ṭāʾif den Propheten ﷺ mit Steinen vertrieb. Auf dem Rückweg, in Nachla, hörte eine Schar Dschinn den Koran (46:29–32; vgl. Lektion 40). Die Sure ist Trost: Wenn die Menschen ablehnen, gibt es andere Hörer – und die großen Gesandten vor dir haben dasselbe durchgemacht.",
"Die Aḥqāf (Sanddünen) sind die Region des Volkes ʿĀd im Süden Arabiens, zwischen Jemen und Oman (die Gegend des heutigen Rubʿ al-Chālī). Hūd warnte sie dort (vgl. Lektion 37 und 39).",
"46:10 spricht von „einem Zeugen von den Kindern Isrāʾīl“, der die Wahrheit des Korans bezeugte und glaubte. Saʿd ibn Abī Waqqāṣ sagte, dieser Vers sei über ʿAbdullāh ibn Salām herabgekommen, einen jüdischen Gelehrten Medinas, der Muslim wurde (Sahih al-Buchari, Nr. 3812). Da ʿAbdullāh ibn Salām erst in Medina Muslim wurde, halten viele diesen Vers für medinensisch innerhalb einer mekkanischen Sure."],
asbab: [
 {text: "46:10 („ein Zeuge von den Kindern Isrāʾīl“): nach Saʿd ibn Abī Waqqāṣ über ʿAbdullāh ibn Salām herabgesandt.", quelle: "Sahih al-Buchari, Nr. 3812"},
 {text: "46:17 („Pfui über euch beide!“): Marwān behauptete, der Vers sei über ʿAbd ar-Raḥmān ibn Abī Bakr herabgekommen. ʿĀʾischa widersprach: „Allah hat über uns nichts im Koran herabgesandt außer meiner Unschuld.“ Der Vers beschreibt also einen allgemeinen Typus.", quelle: "Sahih al-Buchari, Nr. 4827"},
 {text: "46:29–32: die Schar der Dschinn, die den Koran hörte (vgl. Lektion 40).", quelle: "Sahih al-Buchari, Nr. 773; Sahih Muslim, Nr. 449"}
],
begriffe: [
 {arab: "الْأَحْقَاف", tr: "al-aḥqāf", wurzel: "ḥ-q-f", erkl: "„Die (gewundenen) Sanddünen“ (46:21) – die Heimat des Volkes ʿĀd. Ein Volk, das mächtige Bauten hatte, liegt heute unter Sand."},
 {arab: "بِدْعًا مِّنَ الرُّسُل", tr: "bidʿan mina r-rusul", wurzel: "b-d-ʿ", erkl: "„Ich bin keine Neuheit unter den Gesandten“ (46:9) – der Prophet ﷺ ist nicht der erste; seine Botschaft ist die der früheren Propheten. „Und ich weiß nicht, was mit mir und mit euch geschehen wird“ – Demut gegenüber dem Verborgenen (vgl. Lektion 40)."},
 {arab: "حَمْلُهُ وَفِصَالُهُ ثَلَاثُونَ شَهْرًا", tr: "ḥamluhu wa-fiṣāluhu thalāthūna schahrā", wurzel: "f-ṣ-l", erkl: "„Seine Schwangerschaft und Entwöhnung dauern dreißig Monate“ (46:15). Zusammen mit 2:233 (zwei volle Jahre Stillzeit) leitete ʿAlī ab: Die kürzeste Schwangerschaft beträgt sechs Monate."},
 {arab: "أَوْزِعْنِي", tr: "auziʿnī", wurzel: "w-z-ʿ", erkl: "„Gib mir ein / sporne mich an“ (46:15) – die Bitte um innere Kraft zur Dankbarkeit. Man bittet nicht nur um Gaben, sondern um die Fähigkeit, für sie zu danken."},
 {arab: "أُفٍّ لَّكُمَا", tr: "uffin lakumā", wurzel: "ʾ-f-f", erkl: "„Pfui über euch beide!“ (46:17) – das, was 17:23 ausdrücklich verbietet: „Sag zu ihnen nicht uff.“ Der respektlose Sohn als Gegenbild zum dankbaren."},
 {arab: "أُولُو الْعَزْم", tr: "ulū l-ʿazm", wurzel: "ʿ-z-m", erkl: "„Die mit Entschlossenheit“ (46:35) – nach der Mehrheit die fünf großen Gesandten: Nūḥ, Ibrāhīm, Mūsā, ʿĪsā und Muhammad ﷺ (vgl. 42:13 in Lektion 62). Ihre Geduld ist das Vorbild."}
],
tafsir: [
 {vers: "Verse 1–14: Beweise und der Zeuge", text: "Die Götzen haben nichts erschaffen – „bringt mir eine Schrift vor dieser oder eine Spur von Wissen“ (46:4). Und die Angerufenen hören nicht einmal: „Wer ist weiter irregegangen als der, der neben Allah jemanden anruft, der ihm bis zum Tag der Auferstehung nicht antwortet?“ (46:5). Der Prophet ﷺ: „Ich bin keine Neuheit unter den Gesandten“ (46:9). Dann 46:10: der Zeuge aus den Kindern Isrāʾīl. Und 46:11: Die Hochmütigen sagen über die armen Gläubigen: „Wäre es etwas Gutes, wären sie uns nicht damit zuvorgekommen.“ Ibn Kathīr: Der Hochmut misst Wahrheit an der sozialen Stellung derer, die sie annehmen. Dann 46:13: „Diejenigen, die sagen: Unser Herr ist Allah, und dann standhaft bleiben – keine Furcht ist über ihnen“ (vgl. 41:30 in Lektion 61)."},
 {vers: "Verse 15–20: die zwei Söhne", text: "46:15: Allah befiehlt Güte zu den Eltern; die Mutter trug ihn mit Mühe und gebar ihn mit Mühe, Schwangerschaft und Entwöhnung dauern dreißig Monate. „Wenn er dann seine volle Kraft erreicht und vierzig Jahre erreicht hat, sagt er: Mein Herr, gib mir ein, dankbar zu sein … und mache mir meine Nachkommen rechtschaffen. Ich wende mich Dir reuig zu und gehöre zu den Muslimen.“ As-Saʿdī: Vierzig ist das Alter der vollen Reife – das Alter, in dem auch der Prophet ﷺ berufen wurde; ein Mensch sollte spätestens dann Bilanz ziehen. Allah verspricht ihnen, ihre schlechten Taten zu übergehen (46:16). Dann das Gegenbild 46:17: der Sohn, der „uff“ sagt und die Auferstehung verspottet, während seine Eltern Allah um Hilfe rufen und ihn anflehen: „Wehe dir, glaube!“ Für ihn bewahrheitet sich das Wort. 46:20: „Ihr habt eure guten Dinge in eurem diesseitigen Leben verbraucht“ – ʿUmar sagte, er fürchte, seine guten Dinge schon im Diesseits zu verbrauchen, und hielt sich deshalb einfach."},
 {vers: "Verse 21–28: ʿĀd in den Dünen", text: "Hūd warnte sein Volk in den Aḥqāf. Sie sagten: „Bring uns doch, was du uns androhst!“ Als sie eine Wolke auf ihre Täler zukommen sahen, sagten sie: „Das ist eine Wolke, die uns Regen bringt.“ – „Nein, es ist das, was ihr zu beschleunigen verlangtet: ein Wind mit schmerzhafter Strafe, der alles zerstört auf Befehl seines Herrn“ (46:24–25). ʿĀʾischa berichtet: Wenn der Prophet ﷺ eine Wolke oder Wind sah, erkannte man es an seinem Gesicht; sie fragte ihn, und er sagte: „Was garantiert mir, dass darin keine Strafe ist? Ein Volk wurde mit Wind bestraft, und als sie die Strafe sahen, sagten sie: Das ist eine Wolke, die uns Regen bringt“ (Sahih al-Buchari, Nr. 4829; Sahih Muslim, Nr. 899). Dann 46:26: Sie hatten Gehör, Augen und Herzen – „doch nichts davon nützte ihnen“."},
 {vers: "Verse 29–35: die Dschinn und die Geduld", text: "Die Schar der Dschinn hört den Koran: „Seid still!“ – dann kehren sie als Warner zurück: „Unser Volk, wir haben ein Buch gehört, das nach Mūsā herabgesandt wurde … Folgt dem Rufer Allahs“ (46:29–31). Ibn Kathīr: Der Hinweis „nach Mūsā“ – die Dschinn kannten die Tora. Dann das Auferstehungsargument: Der, der Himmel und Erde erschuf und dabei nicht ermüdete, kann die Toten lebendig machen (46:33). Der Schluss ist Trost und Befehl zugleich: „So sei geduldig, wie die Gesandten mit Entschlossenheit geduldig waren, und wünsche (die Strafe) für sie nicht herbei“ (46:35). Am Tag, an dem sie sehen, was ihnen angedroht wurde, wird es ihnen vorkommen, als hätten sie nur eine Stunde eines Tages verweilt."}
],
ahadith: [
 {text: "Saʿd ibn Abī Waqqāṣ: 46:10 kam über ʿAbdullāh ibn Salām herab.", quelle: "Sahih al-Buchari, Nr. 3812"},
 {text: "ʿĀʾischa: „Allah hat über uns (die Familie Abū Bakrs) nichts im Koran herabgesandt außer meiner Unschuld“ – gegen die Behauptung, 46:17 betreffe ihren Bruder.", quelle: "Sahih al-Buchari, Nr. 4827"},
 {text: "ʿĀʾischa: Wenn der Prophet ﷺ eine Wolke sah, zeigte sich Besorgnis in seinem Gesicht: „Ein Volk wurde mit Wind bestraft …“", quelle: "Sahih al-Buchari, Nr. 4829; Sahih Muslim, Nr. 899"},
 {text: "„Die Zufriedenheit des Herrn liegt in der Zufriedenheit des Vaters, und der Zorn des Herrn liegt im Zorn des Vaters.“ – zu 46:15–17.", quelle: "Sunan at-Tirmidhī, Nr. 1899; sahih"}
],
hanafi: "46:15 ist die Grundlage einer bekannten Rechtsfrage: Wenn Schwangerschaft und Entwöhnung zusammen 30 Monate dauern und die volle Stillzeit zwei Jahre beträgt (2:233), bleibt als kürzeste Schwangerschaftsdauer sechs Monate – so ʿAlī, und alle vier Schulen folgen dem für die Abstammung (nasab). In der hanafitischen Schule gibt es zur Stillzeit eine bekannte Meinungsverschiedenheit: Abū Ḥanīfa hielt 30 Monate für die Höchstdauer, in der Stillen die Milchverwandtschaft (riḍāʿ) begründet; seine Schüler Abū Yūsuf und Muḥammad sagten zwei Jahre – und nach ihrer Meinung wird in der Schule die Fatwa gegeben.",
umsetzung: [
 "Lerne das Duʿā von 46:15 (rabbi auziʿnī an aschkura niʿmatak …) – egal wie alt du bist. Wenn du vierzig bist oder dich näherst: Mach Bilanz und eine bewusste Tauba.",
 "Prüfe deinen Ton mit den Eltern (46:17): Kein ‚uff', kein Augenrollen, kein Anfahren – auch nicht bei religiösen Meinungsverschiedenheiten.",
 "Mach es wie der Prophet ﷺ bei Wolken (Buchari 4829): Lass dich bei Naturereignissen – Sturm, Unwetter – an Allah erinnern und sprich Duʿā.",
 "Wenn deine Daʿwa nicht angenommen wird: Lies 46:35 und erinnere dich an die ulū l-ʿazm – Geduld ist der Weg der Größten."
]
}
];
